import{f as o,o as a,c,a2 as d}from"./chunks/framework.BtbFyp-E.js";const m=JSON.parse('{"title":"03 — AFIP/ARCA: facturación electrónica, padrón e IVA","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/reglas-negocio/03-afip-facturacion-electronica-e-iva.md","filePath":"relevamiento/reglas-negocio/03-afip-facturacion-electronica-e-iva.md","lastUpdated":null}'),t={name:"relevamiento/reglas-negocio/03-afip-facturacion-electronica-e-iva.md"};function r(n,e,i,s,l,p){return a(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="_03-—-afip-arca-facturacion-electronica-padron-e-iva" tabindex="-1">03 — AFIP/ARCA: facturación electrónica, padrón e IVA <a class="header-anchor" href="#_03-—-afip-arca-facturacion-electronica-padron-e-iva" aria-label="Permalink to &quot;03 — AFIP/ARCA: facturación electrónica, padrón e IVA&quot;">​</a></h1><p>Reglas extraídas del código descompilado de Procoop 10.4.6.722. Todas las referencias <code>archivo:línea</code> son relativas a <code>binarios/decompilado/ReglasNegocio/</code> salvo que se indique otra carpeta (<code>ProcoopNet/</code>, <code>Configuracion/</code>). El código es de terceros: acá solo se describe el comportamiento, con pseudocódigo breve cuando ayuda.</p><p>En el código conviven los nombres &quot;AFIP&quot; (clases, tablas, URLs) y &quot;ARCA&quot; (mensajes al usuario y descripciones de parámetros, actualizados después del cambio de nombre del organismo en 2024). En este documento se usa &quot;AFIP&quot; para referirse a lo que está en el código y &quot;ARCA&quot; para lo que aplica hoy.</p><h2 id="fuentes-revisadas" tabindex="-1">Fuentes revisadas <a class="header-anchor" href="#fuentes-revisadas" aria-label="Permalink to &quot;Fuentes revisadas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fuente</th><th>Qué contiene</th></tr></thead><tbody><tr><td><code>ReglasNegocio.Facturacion/clsFacturacionElectronica.cs</code> (2892 líneas)</td><td>Ticket WSAA, autorización CAE/CAEA, consultas, inconsistencias, carpetas IN/OUT, padrón</td></tr><tr><td><code>ReglasNegocio.WSAA/LoginCMSService.cs</code></td><td>Proxy SOAP de WSAA (<code>loginCms</code>)</td></tr><tr><td><code>ReglasNegocio.WSFEV1/*.cs</code> (114 archivos)</td><td>Proxy SOAP de WSFEv1 (<code>Service.cs</code> y DTOs)</td></tr><tr><td><code>ReglasNegocio.WSPA13/*.cs</code></td><td>Proxy del padrón A13 (<code>getIdPersonaListByDocumento</code>, <code>getPersona</code>)</td></tr><tr><td><code>ReglasNegocio.WSPN3/*.cs</code></td><td>Proxy del padrón PUC &quot;Contribuyente Nivel 3&quot; (<code>get</code>)</td></tr><tr><td><code>ReglasNegocio.Facturacion/clsLibroIVA.cs</code> (2524)</td><td>Libro IVA ventas, criterios facturado/percibido, carátula, exportaciones</td></tr><tr><td><code>ReglasNegocio.Facturacion/clsLibroIVAdigital.cs</code> (616)</td><td>Comparación del libro contra lo registrado en AFIP (&quot;Mis Comprobantes&quot;)</td></tr><tr><td><code>ReglasNegocio.Facturacion.Archivos/RG3685.cs</code>, <code>RG3571.cs</code>, <code>TipoArchivos.cs</code></td><td>Formatos de exportación (CITI / Libro IVA digital, RCSP, etc.)</td></tr><tr><td><code>ReglasNegocio.Facturacion/clsFacturacionVarios.cs</code> (847)</td><td>Comprobantes de administración pública</td></tr><tr><td><code>ReglasNegocio.Facturacion/clsComprobante.cs</code>, <code>clsFacturacionMasiva.cs</code>, <code>clsAnulacionFacturas.cs</code></td><td>Asignación de CAE/CAEA/CAI/CESP al emitir y validaciones de CESP</td></tr><tr><td><code>ReglasNegocio.Varios.Generales/clsServicio_Procoop.cs</code></td><td>Agente que autoriza en segundo plano</td></tr><tr><td><code>ReglasNegocio.Varios/clsImportacionArchivos.cs</code></td><td>Importación del padrón de condición tributaria (tabla <code>EMPAFIP</code>)</td></tr><tr><td><code>CapaNucleo/clsVariables.cs</code></td><td>Descripción de los parámetros <code>Busca_V2_*</code></td></tr></tbody></table><p>Tablas involucradas (ver <code>binarios/CapaDatos-tablas.md</code>): <code>FACTURAS</code>, <code>ITEMSFAC</code>, <code>COMPROB</code> (campo <code>COD_AFIP</code>, <code>TIPO_SIT</code>, <code>DEB_CRE</code>, <code>INTERNO</code>), <code>COMPPOS</code> (comprobante × punto de venta, flags <code>CAE</code>, <code>CAEA</code>, <code>CAI</code>), <code>PTOVENTA</code> (flag <code>PAUSAR</code>), <code>SITIVA</code> (campos <code>AFIP_SIT</code>, <code>COD_AFIP</code>, <code>COD_EMPAFIP</code>, <code>IVARI</code>, <code>PERCIBIDO</code>, <code>CSP_DEF</code>, <code>SPU_DEF</code>), <code>DOCUMENT</code> (<code>COD_AFIP</code> del tipo de documento), <code>RELACION_COMP</code>, <code>CESPAFIP</code>, <code>EMPAFIP</code>, <code>ACTAFIP</code>, <code>ELECTRONICA_FC</code> / <code>ELECTRONICA_IVA</code> / <code>ELECTRONICA_TRIB</code> / <code>ELECTRONICA_RELCOMP</code>, <code>COMPROBANTES_ADM</code>, <code>IVACOM</code> / <code>FPALIC_IVA</code> (compras).</p><hr><h2 id="_1-dos-modos-de-operacion" tabindex="-1">1. Dos modos de operación <a class="header-anchor" href="#_1-dos-modos-de-operacion" aria-label="Permalink to &quot;1. Dos modos de operación&quot;">​</a></h2><p>Procoop puede funcionar de dos maneras frente a AFIP (<code>clsFacturacionElectronica.ModoSistema</code>, <code>clsFacturacionElectronica.cs:195-199</code>):</p><ul><li><strong>Completo</strong>: los comprobantes nacen en Procoop (<code>FACTURAS</code>). Un comprobante que requiere CAE se graba &quot;bloqueado&quot; (<code>FACTURAS.ID_BLO = -1</code>, <code>clsComprobante.cs:789</code>, <code>clsComprobanteFactura.cs:1128</code>) y queda pendiente hasta que se autoriza.</li><li><strong>Solo factura electrónica</strong> (<code>Nucleo.objConfig.SoloElectronica</code>): Procoop actúa como pasarela de autorización para comprobantes generados por otro sistema. Los comprobantes entran por archivos CSV a una carpeta de entrada, se guardan en <code>ELECTRONICA_FC</code> y el resultado (CAE o error) se devuelve en archivos a una carpeta de salida (sección 6). En este modo se crean solo las tablas <code>ELECTRONICA*</code> más algunas de soporte (<code>clsChequeos_Estructura.cs:979-986</code>) y se piden solo los parámetros 519, 2082, 2083 y de backup (<code>clsVariables.cs:100-108</code>).</li></ul><h2 id="_2-autenticacion-wsaa" tabindex="-1">2. Autenticación WSAA <a class="header-anchor" href="#_2-autenticacion-wsaa" aria-label="Permalink to &quot;2. Autenticación WSAA&quot;">​</a></h2><h3 id="_2-1-configuracion" tabindex="-1">2.1 Configuración <a class="header-anchor" href="#_2-1-configuracion" aria-label="Permalink to &quot;2.1 Configuración&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parámetro</th><th>Descripción (de <code>clsVariables.cs</code>)</th><th>Uso</th></tr></thead><tbody><tr><td>2071</td><td>Path de Certificado ARCA</td><td>Archivo del certificado con clave privada (<code>clsFacturacionElectronica.cs:809</code>)</td></tr><tr><td>2072</td><td>URL ARCA para obtención de Ticket de Autenticación</td><td>Endpoint WSAA (<code>:808</code>)</td></tr><tr><td>2073</td><td>URL ARCA para Registración de Facturas electrónicas</td><td>Endpoint WSFEv1 (<code>:495</code>)</td></tr><tr><td>2925</td><td>Vencimiento Certificado ARCA (obtenido de Certificado)</td><td>Se actualiza solo, con el <code>NotAfter</code> del certificado (<code>:335-338</code>)</td></tr></tbody></table><p>Los valores por defecto del proxy apuntan a <strong>homologación</strong> (<code>wsaahomo.afip.gov.ar</code>, <code>wswhomo.afip.gov.ar</code>, <code>ReglasNegocio.Properties/Settings.cs:19-25</code>); producción se configura por los parámetros 2072/2073. En cambio, las URLs de padrón están fijas en código y son de producción (<code>clsFacturacionElectronica.cs:501-514</code>).</p><p><code>CargarTicket(WS = &quot;wsfe&quot;)</code> (<code>clsFacturacionElectronica.cs:801-849</code>) valida antes de pedir nada:</p><ol><li>Si la base es DEMO, no permite facturación electrónica.</li><li>El archivo del certificado (2071) debe existir; las URLs 2072 y 2073 no pueden estar vacías (la 2073 se exige incluso cuando el ticket es para padrón).</li><li>Si ya hay un ticket en memoria para el mismo servicio y no expiró, lo reutiliza.</li><li>Si no, crea un <code>LoginTicket</code> y llama a <code>GetTicket</code>.</li></ol><h3 id="_2-2-ticket-de-acceso-y-cache" tabindex="-1">2.2 Ticket de acceso y caché <a class="header-anchor" href="#_2-2-ticket-de-acceso-y-cache" aria-label="Permalink to &quot;2.2 Ticket de acceso y caché&quot;">​</a></h3><p><code>LoginTicket.GetTicket</code> (<code>clsFacturacionElectronica.cs:293-302</code>) usa un <strong>caché en archivo</strong>: <code>&amp;lt;carpeta &quot;Electronica&quot; del servidor&gt;\\TA&amp;lt;servicio&gt;.xml</code> (por ejemplo <code>TAwsfe.xml</code>). Si el archivo existe y el ticket guardado sigue vigente, lo usa; si no, pide uno nuevo. Hay entonces dos niveles de caché: memoria (por instancia de la clase) y archivo (compartido por todas las terminales que ven la carpeta del servidor).</p><p>Obtención de un ticket nuevo (<code>ObtenerLoginTicketResponse</code>, <code>:304-375</code>):</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>armar loginTicketRequest:</span></span>
<span class="line"><span>  uniqueId       = contador estático del proceso (arranca en 0 en cada ejecución)</span></span>
<span class="line"><span>  generationTime = ahora − 10 minutos</span></span>
<span class="line"><span>  expirationTime = ahora + 10 minutos</span></span>
<span class="line"><span>  service        = &quot;wsfe&quot; | &quot;ws_sr_padron_a13&quot; | &quot;WSPN3&quot;</span></span>
<span class="line"><span>firmar el XML como CMS/PKCS#7 con el certificado (incluye solo el certificado final)</span></span>
<span class="line"><span>actualizar parámetro 2925 con la fecha de vencimiento del certificado</span></span>
<span class="line"><span>llamar loginCms(CMS en base64)</span></span>
<span class="line"><span>  si la excepción contiene &quot;expirado&quot; → mensaje &quot;certificado vencido, ARCA no autorizará más comprobantes&quot;</span></span>
<span class="line"><span>guardar la respuesta en TA&lt;servicio&gt;.xml y cargarla</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><ul><li>El certificado se lee con <code>X509Certificate2.Import(bytes del archivo)</code> sin contraseña (<code>:438-450</code>): el archivo tiene que ser un PFX/P12 con la clave privada y <strong>sin clave</strong>.</li><li>La firma está en <code>CertificadosX509Lib.FirmaBytesMensaje</code> (<code>:421-436</code>).</li></ul><p>Lectura del ticket (<code>CargarTicket(PathArchivo)</code>, <code>:377-416</code>): toma <code>uniqueId</code>, <code>generationTime</code>, <code>expirationTime</code>, <code>sign</code> y <code>token</code>; decodifica el token (base64 → XML <code>sso</code>) para sacar el <strong>CUIT representado</strong> de <code>/sso/operation/login/relations/relation</code>. Si hay una sola relación usa esa; si hay más de una, usa <strong>la segunda</strong> (<code>:394-401</code>), lo que supone un orden fijo en la respuesta. El ticket es válido mientras <code>expirationTime &gt; ahora</code>.</p><p><code>GetTicketFirmante</code> (<code>:745-757</code>) devuelve el CUIT del ticket o, si no se puede obtener, lo extrae del <em>subject</em> del certificado (texto que sigue a <code>&quot;=CUIT &quot;</code>).</p><p>El constructor fuerza TLS 1.2 y el destructor restaura el protocolo anterior (<code>:551-560</code>). El cliente WSFEv1 usa un timeout de 90 s (<code>:492-499</code>).</p><h3 id="_2-3-avisos-de-vencimiento" tabindex="-1">2.3 Avisos de vencimiento <a class="header-anchor" href="#_2-3-avisos-de-vencimiento" aria-label="Permalink to &quot;2.3 Avisos de vencimiento&quot;">​</a></h3><p>Al iniciar Procoop (<code>ProcoopNet/Procoop/Inicio_ProCoop.cs:1381-1385</code> y <code>:1255-1275</code>), si el certificado vence en 14 días o menos se muestra un aviso (asterisco hasta 7 días, exclamación de 7 a 3, error en los últimos 3 días o si ya venció). Solo lo ven los usuarios con el permiso <code>ControlTitularesProcoopWeb</code>.</p><h2 id="_3-autorizacion-con-cae-fecaesolicitar" tabindex="-1">3. Autorización con CAE (FECAESolicitar) <a class="header-anchor" href="#_3-autorizacion-con-cae-fecaesolicitar" aria-label="Permalink to &quot;3. Autorización con CAE (FECAESolicitar)&quot;">​</a></h2><h3 id="_3-1-cola-de-pendientes-y-disparadores" tabindex="-1">3.1 Cola de pendientes y disparadores <a class="header-anchor" href="#_3-1-cola-de-pendientes-y-disparadores" aria-label="Permalink to &quot;3.1 Cola de pendientes y disparadores&quot;">​</a></h3><p><code>GetPendientes</code> (<code>clsFacturacionElectronica.cs:588-743</code>):</p><ul><li><strong>Modo completo</strong>: <code>FACTURAS</code> cuyo comprobante y punto de venta tienen <code>COMPPOS.CAE = true</code> y cuyo punto de venta no está pausado (<code>PTOVENTA.PAUSAR = false</code>). Se considera pendiente si <code>ID_BLO = -1</code>. El código AFIP sale de <code>COMPROB.COD_AFIP</code>; el importe total es <code>TOTAL1 + IMP_ANTI</code>; se marca <code>Comp_RI</code> si <code>COMPROB.TIPO_SIT = 1</code>. Para cada par comprobante/punto de venta calcula el último número autorizado localmente (máximo <code>NUM_COM</code> con <code>VTOCAE</code> cargado).</li><li><strong>Modo solo electrónica</strong>: <code>ELECTRONICA_FC</code> sin <code>VTOCAE</code>. Ahí <code>COD_COM</code> ya es el código AFIP y <code>Comp_RI</code> se deduce de <code>CLIENTE_TIPDNI = 80</code>.</li></ul><p>El estado visible es <em>Procesando</em>, <em>Autorizado</em> (tiene <code>VTOCAE</code>) o <em>Pendiente</em> (<code>:233-247</code>).</p><p>Quién dispara la autorización:</p><ul><li><strong>Agente / servicio</strong> (<code>clsServicio_Procoop.RegistrarFacturasElectronicas</code>, <code>clsServicio_Procoop.cs:470-483</code>): agrupa los pendientes por tipo y punto de venta, los ordena por número y los manda en <strong>tandas de 100</strong> (<code>:1940-1964</code>). Corta en el primer error y lo registra en el log.</li><li>El parámetro <strong>726</strong> &quot;Autorizar Facturas con cliente ARCA automáticamente&quot; (propiedad <code>RegistrarFacturasAuto</code>, <code>clsFacturacionElectronica.cs:478-491</code>) se prende y apaga desde el ícono de notificación (<code>ProcoopNet/Procoop.Forms/IconoNotificacion.cs:241-243</code>). La facturación masiva lo pone en <code>false</code> cuando quedan facturas bloqueadas (<code>clsFacturacionMasiva.cs:883-887</code>).</li><li><strong>Espera sincrónica</strong>: si el parámetro <strong>727</strong> &quot;Aguardar a que se registre en ARCA la factura&quot; está activo, al registrar una venta o una cobranza que genera factura se consulta la base 15 veces con 1 s de pausa, esperando que el agente desbloquee la factura (<code>ChequearRegistracion</code>, <code>clsFacturacionElectronica.cs:937-966</code>; usos en <code>clsComprobanteVenta.cs:631-683</code> y <code>clsRegistracionCobranza.cs:198-207</code>). Si no llega, la operación queda registrada con el aviso &quot;no se pudo autorizar en ARCA&quot;.</li><li><strong>Aviso al iniciar</strong>: si hay facturas con <code>ID_BLO = -1</code> y fecha de hace más de 3 días (<code>clsFacturacionMasiva.ValidarElectronicas</code>, <code>:300-308</code>), se muestra un aviso y la lista de pendientes (<code>Inicio_ProCoop.cs:1356-1363</code>).</li></ul><h3 id="_3-2-bloqueo-y-validaciones-previas" tabindex="-1">3.2 Bloqueo y validaciones previas <a class="header-anchor" href="#_3-2-bloqueo-y-validaciones-previas" aria-label="Permalink to &quot;3.2 Bloqueo y validaciones previas&quot;">​</a></h3><p><code>RegistrarFacturas(lista, modo, consulta)</code> (<code>clsFacturacionElectronica.cs:851-924</code>):</p><ul><li><strong>Completo</strong>: bloquea las filas con <code>BloquearRegistro(&quot;FACTURAS&quot;, &quot;ID_FAC in (...) and VtoCAE is null&quot;, transacción, 15)</code>. Si autoriza hace <em>commit</em>; si falla, <em>rollback</em>. Si no logra el bloqueo devuelve <code>true</code> sin hacer nada (otro proceso está trabajando).</li><li><strong>Solo electrónica</strong>: marca <code>PROCESANDO = 1</code> con un <code>UPDATE ... WHERE PROCESANDO = 0</code>. Si la cantidad de filas actualizadas no coincide, aborta; al final siempre vuelve <code>PROCESANDO = 0</code>.</li></ul><p>Validaciones del método privado (<code>:968-1010</code>):</p><ol><li>Todas las facturas deben estar bloqueadas (<code>ID_BLO = -1</code>).</li><li><strong>No puede haber una factura anterior pendiente</strong> del mismo comprobante y punto de venta (número menor con <code>ID_BLO = -1</code>) → &quot;No es posible autorizar la factura en ARCA ya que hay una factura anterior pendiente de autorización&quot;.</li><li>Ticket válido.</li><li>En modo &quot;solo consulta&quot; no autoriza: recupera el CAE con <code>FECompConsultar</code> (sección 3.7).</li></ol><p>En <code>AutorizaFacturas</code> (<code>:1981-2186</code>):</p><ol start="5"><li><code>COMPROB.COD_AFIP</code> tiene que ser numérico; si no → &quot;Debe configurar el código ARCA del Comprobante …&quot;.</li><li><strong>Numeración correlativa</strong>: si el rango tiene huecos, informa el primer número faltante y no envía nada (<code>:1997-2006</code>).</li></ol><h3 id="_3-3-agrupacion-en-lotes" tabindex="-1">3.3 Agrupación en lotes <a class="header-anchor" href="#_3-3-agrupacion-en-lotes" aria-label="Permalink to &quot;3.3 Agrupación en lotes&quot;">​</a></h3><p>Para los códigos AFIP <strong>6, 7, 8, 9, 10, 11, 12, 13, 15, 35, 40, 49, 61, 64</strong> (facturas, notas de débito y crédito B y C, y similares) se agrupan comprobantes consecutivos en un único detalle <code>CbteDesde..CbteHasta</code> (<code>:1992-1996</code>, <code>:2010-2026</code>). La regla para abrir un detalle nuevo es:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nuevo detalle si:</span></span>
<span class="line"><span>  no es agrupable, o</span></span>
<span class="line"><span>  el número no es el siguiente al último del lote, o</span></span>
<span class="line"><span>  TOTAL1 del comprobante &gt; máximo (parámetro 2712, por defecto 5000), o</span></span>
<span class="line"><span>  el lote actual tiene un solo comprobante y su total supera el máximo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>En un lote el receptor se envía como <code>DocTipo = 99</code>, <code>DocNro = 0</code>; los importes se suman y las alícuotas y tributos se fusionan por código. En modo solo electrónica el máximo está fijo en 5000 en lugar de usar el parámetro (<code>:2228</code>). Existe además el parámetro 2427 &quot;Importe Máximo para autorizar los comprobantes de Facturas Electrónicas&quot;, pero no se encontró dónde se usa.</p><h3 id="_3-4-armado-del-detalle-getdetrequest-para-facturas-2349-2627" tabindex="-1">3.4 Armado del detalle (<code>GetDetRequest</code> para <code>FACTURAS</code>, <code>:2349-2627</code>) <a class="header-anchor" href="#_3-4-armado-del-detalle-getdetrequest-para-facturas-2349-2627" aria-label="Permalink to &quot;3.4 Armado del detalle (\`GetDetRequest\` para \`FACTURAS\`, \`:2349-2627\`)&quot;">​</a></h3><p><strong>Receptor</strong></p><ul><li><code>DocTipo</code> = 80 (CUIT) si <code>COMPROB.TIPO_SIT = 1</code> (comprobante para responsable inscripto); si no, el <code>COD_AFIP</code> del tipo de documento de la persona (<code>DOCUMENT.COD_AFIP</code>).</li><li><code>DocNro</code> = <code>SOCIOS.CUIT</code> si es 80, o <code>PERSONAS.NUM_DNI</code>, sin guiones. Si no se puede convertir a número y el parámetro <strong>2780</strong> &quot;No utilizar CUIT genérico&quot; está apagado, usa el <strong>CUIT genérico 23333333333</strong>.</li><li>Si es CUIT pero el número tiene 8 dígitos (un DNI), <strong>genera el CUIT</strong> a partir del DNI y el sexo (<code>Impuestos.GenerarCuit</code>, <code>:2365-2368</code>).</li><li>Si <code>DocTipo = 99</code>, <code>DocNro = 0</code>.</li><li><code>CondicionIVAReceptorId</code> = <code>SITIVA.AFIP_SIT</code> de la situación IVA de la factura, si no es 0 (<code>:2424-2429</code>).</li></ul><p><strong>Concepto y fechas de servicio</strong></p><ul><li>Concepto 1 (productos) si hay ítems de tipo 1; 2 (servicios) si solo hay tipo 2; 3 si hay de ambos; 1 si la factura no tiene ítems (<code>:2369-2377</code>). En un lote, si se mezclan, pasa a 3.</li><li>Si el concepto no es 1, <code>FchServDesde</code> / <code>FchServHasta</code> son el primer y el último día del <strong>período facturado</strong> (<code>FACTURAS.PERIODO</code>); si el período no se puede convertir, del mes de la fecha de emisión (<code>:2398-2411</code>).</li><li><code>FchVtoPago</code> = primer vencimiento (<code>VTO1</code>) cuando el concepto es mayor a 1.</li><li><code>CbteFch</code> = fecha de emisión; moneda siempre <code>PES</code> con cotización 1.</li></ul><p><strong>Importes</strong> (<code>:2470-2481</code>; se excluyen ítems de tipo 1 subtipo 5)</p><table tabindex="0"><thead><tr><th>Campo AFIP</th><th>Cómo se calcula</th></tr></thead><tbody><tr><td><code>ImpNeto</code></td><td>Σ precio sin IVA × cantidad de ítems sin impuesto asociado y con alícuota ≠ 0</td></tr><tr><td><code>ImpOpEx</code></td><td>Ídem con alícuota 0 (excluye ítems de tipo 5)</td></tr><tr><td><code>ImpTotConc</code></td><td>Ítems de impuesto con <code>IMPUESTO.ORIGEN = 0</code> y subtipo 0</td></tr><tr><td><code>ImpTotal</code></td><td><code>TOTAL1 + IMP_ANTI</code></td></tr><tr><td><code>ImpIVA</code></td><td>Σ de las alícuotas informadas</td></tr><tr><td><code>ImpTrib</code></td><td>Σ de los tributos informados</td></tr></tbody></table><p>Para las facturas y notas de crédito C (códigos 11 y 13) el exento se suma al neto y <code>ImpOpEx</code> queda en 0.</p><p><strong>Alícuotas de IVA</strong> (<code>:2482-2515</code>): se toman los ítems de impuesto (tipo 4) que no son subtipo 0 ni 4, se agrupan por porcentaje y se cruzan con la tabla fija <code>GetAlicuotasAfip</code> (<code>:2856-2891</code>):</p><table tabindex="0"><thead><tr><th>Id AFIP</th><th>3</th><th>4</th><th>5</th><th>6</th><th>8</th><th>9</th></tr></thead><tbody><tr><td>%</td><td>0</td><td>10,5</td><td>21</td><td>27</td><td>5</td><td>2,5</td></tr></tbody></table><p>Base = Σ <code>IMP_BI</code>, importe = Σ <code>PRE_VSI</code>. Se descartan las alícuotas con base e importe menores a 0,01; las que quedan en cero van al Id 3. Se redondea a 3 decimales al agrupar y luego a 2 antes de enviar.</p><p><strong>Tributos</strong> (<code>:2516-2550</code>): ítems con impuesto de <code>ORIGEN ≠ 0</code> y subtipo 0 o 4. El Id del tributo es directamente <code>IMPUESTO.ORIGEN</code>; los ítems de subtipo 4 (percepciones) se envían con Id 3. Se agrupan por Id con alícuota, base, descripción e importe. La correspondencia está verificada en la segunda pasada y es incorrecta para municipales, nacionales y percepciones (ver §12.2).</p><p><strong>Ajustes finales antes de enviar</strong> (<code>:2028-2069</code>)</p><ul><li>Todos los importes se redondean a 2 decimales.</li><li>Si <code>ImpTotal ≤ 0,03</code> se manda todo como exento, sin IVA.</li><li>Si <code>ImpTotal − (conceptos sumados)</code> da una diferencia positiva menor a 0,03, se suma al exento para que cierre.</li></ul><p><strong>Factura de Crédito Electrónica MiPyME</strong> (códigos 201 a 213, <code>:2436-2464</code>)</p><ul><li><code>FchVtoPago</code> = primer vencimiento; se anula para las notas de crédito y para el 202.</li><li>Opcional <strong>2101</strong> = CBU (parámetro 2431) y <strong>2102</strong> = alias (parámetro 2432), salvo en notas de débito y crédito (202, 203, 207, 208, 212, 213).</li><li>Opcional <strong>27</strong> = <code>SCA</code> (transferencia por el sistema de circulación abierta) para 201, 206 y 211.</li><li>Opcional <strong>22</strong> = <code>S</code>/<code>N</code> (anulación) en las notas de crédito 203, 208 y 213, según <code>RELACION_COMP.ANULACION</code>.</li></ul><p><strong>Comprobantes asociados</strong> (códigos 2, 3, 7, 8, 11, 12, 13, 202, 203, 207, 208, 212, 213, <code>:2551-2621</code>)</p><ul><li>Se informan como <code>CbtesAsoc</code> los comprobantes relacionados (<code>RELACION_COMP</code>) que tienen código AFIP, no son internos, son de clase 0, fueron autorizados con CAE (<code>TP_CODIGO = 2</code>) y no están marcados como <code>NOMOSTRAR</code>. El CUIT asociado es el de la empresa si la relación pide informar el CUIT del emisor; si no, el del receptor cuando tiene 11 dígitos.</li><li>Si las relaciones existen pero ninguna fue autorizada con CAE, se envía <code>PeriodoAsoc</code>: desde el período mínimo de los relacionados (nunca antes del 02/01/2006) hasta fin de ese mes, recortado a la fecha de emisión.</li><li>Para notas de débito y crédito A y B (2, 3, 7, 8) sin asociados, se envía siempre <code>PeriodoAsoc</code> con el período de la propia nota.</li></ul><p><code>ConsultaPreviaAutorizar(id_fac)</code> (<code>:1812-1825</code>) arma el mismo detalle sin enviarlo, para previsualizarlo.</p><h3 id="_3-5-respuesta-errores-y-reintentos" tabindex="-1">3.5 Respuesta, errores y reintentos <a class="header-anchor" href="#_3-5-respuesta-errores-y-reintentos" aria-label="Permalink to &quot;3.5 Respuesta, errores y reintentos&quot;">​</a></h3><p>Después de <code>FECAESolicitar</code> (<code>:2077-2137</code>):</p><ul><li>Por cada factura busca el detalle cuyo rango contiene su número. Con resultado <code>A</code>: graba <code>CAE</code>, <code>VTOCAE</code> (de <code>CAEFchVto</code>, formato <code>yyyyMMdd</code>) y <code>ID_BLO = GetIdBloqueo(...)</code>. Las observaciones se guardan en <code>ErrorCAE</code>, pero se toman del <strong>primer</strong> detalle de la respuesta, no del que corresponde a la factura.</li><li><code>GetIdBloqueo</code> (<code>:2188-2198</code>): si el parámetro <strong>2769</strong> está activo, la factura no se desbloquea del todo: hereda el menor <code>ID_BLO</code> de otras facturas bloqueadas de la misma cuenta con saldo; si no, queda en <code>null</code>.</li></ul><table tabindex="0"><thead><tr><th>Código AFIP</th><th>Tratamiento</th></tr></thead><tbody><tr><td><strong>10016</strong> (número o fecha no es el próximo a autorizar)</td><td>Consulta con <code>FECompConsultar</code> si ese número ya está autorizado (caso típico: respuesta perdida). Si coincide el importe, lo toma como autorizado; si no, informa el último número autorizado según <code>FECompUltimoAutorizado</code>.</td></tr><tr><td><strong>10040</strong> (problema con los comprobantes asociados)</td><td>Marca las relaciones como <code>NOMOSTRAR = 1</code> para que el próximo intento no las envíe. En modo solo electrónica borra las filas de <code>ELECTRONICA_RELCOMP</code>. También se aplica si 10040 llega como observación.</td></tr><tr><td><strong>10242 / 10243</strong> (condición IVA del receptor)</td><td>Reintenta ese comprobante solo, sin agrupar y con <code>CondicionIVAReceptorId = 5</code> (consumidor final).</td></tr><tr><td>Otros</td><td>Concatena <code>Msg + &quot;Cod:&quot; + Code</code> en <code>ErrorCAE</code>.</td></tr></tbody></table><ul><li>Si el resultado de cabecera <strong>no es <code>R</code></strong>, el método devuelve éxito (un resultado parcial <code>P</code> cuenta como OK).</li><li>Si fue rechazado, el envío era agrupado y había más de un comprobante, <strong>reintenta sin agrupar</strong> los que siguen sin <code>VTOCAE</code> (<code>:2174-2177</code>).</li><li><code>ConsultarNumCom</code> (<code>:1062-1082</code>) arma el mensaje &quot;El último comprobante fue el N&quot;.</li></ul><h3 id="_3-6-consultas-auxiliares" tabindex="-1">3.6 Consultas auxiliares <a class="header-anchor" href="#_3-6-consultas-auxiliares" aria-label="Permalink to &quot;3.6 Consultas auxiliares&quot;">​</a></h3><ul><li><code>ConsultarPuntosVenta</code> (<code>:1084-1114</code>): <code>FEParamGetPtosVenta</code>, filtrando los no bloqueados y sin fecha de baja.</li><li><code>ObtenerTabla</code> (<code>:1901-1943</code>): descarga las tablas paramétricas (comprobantes, monedas, IVA, conceptos, tributos, documentos, opcionales, países, condiciones IVA del receptor).</li><li><code>lstComprobantes</code> (<code>:516-549</code>): <code>FEParamGetTiposCbte</code> guardado en memoria; se usa para describir los comprobantes y validar los asociados en modo solo electrónica.</li><li>Hay métodos del proxy que no se usan: <code>FEDummy</code>, <code>FECompTotXRequest</code>, <code>FEParamGetCotizacion</code>, <code>FEParamGetActividades</code>, <code>FECAEASinMovimientoConsultar/Informar</code> (<code>ReglasNegocio.WSFEV1/Service.cs</code>). El DTO de detalle ya tiene <code>Compradores</code> y <code>Actividades</code> (<code>FEDetRequest.cs:377-401</code>), pero nunca se completan.</li></ul><h3 id="_3-7-inconsistencias-conciliacion-contra-afip" tabindex="-1">3.7 Inconsistencias (conciliación contra AFIP) <a class="header-anchor" href="#_3-7-inconsistencias-conciliacion-contra-afip" aria-label="Permalink to &quot;3.7 Inconsistencias (conciliación contra AFIP)&quot;">​</a></h3><p><code>ConsultarInconsistencias(lista, modo)</code> (<code>:1602-1722</code>) procesa los IDs de a 2000 y, por cada comprobante, llama a <code>FECompConsultar</code>:</p><ul><li>Si AFIP devuelve error, lo guarda en <code>ErrorCAE</code>.</li><li>Compara el CAE local con el de AFIP (&quot;El número de CAE no coincide&quot;) y el total local (<code>TOTAL1 + IMP_ANTI</code>, sumando todo el rango si fue un lote) con <code>ImpTotal</code>, con tolerancia de 0,02.</li><li><strong>Repara</strong>: a todos los comprobantes del rango cuyo CAE difiere les copia el CAE y el vencimiento de AFIP, limpia el error y desbloquea (<code>:1740-1790</code>).</li><li>Devuelve un texto con los comprobantes con error, distinguiendo individuales de lotes.</li></ul><p><code>ConsultarCAE</code> privado (<code>:1836-1899</code>): con resultado <code>A</code> y total coincidente (solo se controla en comprobantes individuales), toma el CAE; si era CAEA marca <code>COD_FAC = &quot;P&quot;</code> (informado). En la variante de <code>ELECTRONICA_FC</code> el mensaje de diferencia contiene un <code>{dif}</code> que nunca se reemplaza (<code>:1855</code>).</p><p><code>EliminarFcElectronica</code> (<code>:562-575</code>) borra un comprobante de <code>ELECTRONICA_FC</code> solo si no tiene <code>VTOCAE</code>.</p><h2 id="_4-caea-cai-y-cesp" tabindex="-1">4. CAEA, CAI y CESP <a class="header-anchor" href="#_4-caea-cai-y-cesp" aria-label="Permalink to &quot;4. CAEA, CAI y CESP&quot;">​</a></h2><h3 id="_4-1-que-autorizacion-recibe-cada-comprobante-al-emitirse" tabindex="-1">4.1 Qué autorización recibe cada comprobante al emitirse <a class="header-anchor" href="#_4-1-que-autorizacion-recibe-cada-comprobante-al-emitirse" aria-label="Permalink to &quot;4.1 Qué autorización recibe cada comprobante al emitirse&quot;">​</a></h3><p>Al numerar un comprobante (<code>clsComprobante.cs:800-861</code>) se decide según <code>COMPPOS</code>:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>si COMPPOS.CAEA:</span></span>
<span class="line"><span>   buscar en CESPAFIP una fila con CAEA=1 y FEC_INI &lt;= fecha &lt;= FEC_FIN (y VTO_CESP &lt;= hoy)</span></span>
<span class="line"><span>   si existe → CAE = CESPAFIP.CESP (el código CAEA), VtoCae = VTO_CESP, tipo = CAEA</span></span>
<span class="line"><span>   si no y COMPPOS.CAE → queda bloqueado para pedir CAE</span></span>
<span class="line"><span>si no, si COMPPOS.CAE → bloqueado (ID_BLO = -1), tipo = CAE</span></span>
<span class="line"><span>si no, si COMPPOS.CAI → CAE = COMPPOS.CAI_ACTUAL, VtoCae = VTO_CAI, tipo = CAI</span></span>
<span class="line"><span>si no, si el comprobante es de servicios públicos (SITIVA.CSP_DEF / SPU_DEF):</span></span>
<span class="line"><span>   buscar en CESPAFIP una fila con CAEA=0, FEC_INI &lt;= fecha &lt;= FEC_FIN y VTO_CESP &gt;= hoy</span></span>
<span class="line"><span>   si existe → CAE = CESP, VtoCae = VTO_CESP, tipo = CESP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Los tipos de autorización son <code>CAI = 1, CAE = 2, CESP = 3, CAEA = 4</code> (<code>CapaNucleo/Tipo_Autorizacion.cs</code>) y quedan en <code>FACTURAS.TP_CODIGO</code>. El QR de la factura usa <code>tipoCodAut = &quot;A&quot;</code> cuando es CAEA y <code>&quot;E&quot;</code> en los demás casos (<code>clsFacturasImpresion.cs:948-980</code>).</p><p>La tabla <strong><code>CESPAFIP</code></strong> guarda entonces dos cosas distintas, diferenciadas por el flag <code>CAEA</code>: los <strong>CESP</strong> para liquidaciones de servicios públicos y los <strong>CAEA</strong> quincenales. Columnas usadas: <code>ID_CESP</code>, <code>CESP</code>, <code>FEC_INI</code>, <code>FEC_FIN</code>, <code>VTO_CESP</code>, <code>CAEA</code>.</p><h3 id="_4-2-cesp" tabindex="-1">4.2 CESP <a class="header-anchor" href="#_4-2-cesp" aria-label="Permalink to &quot;4.2 CESP&quot;">​</a></h3><p>En Procoop, el CESP es un código de autorización que AFIP otorga por un período para emitir las <strong>liquidaciones de servicios públicos</strong> (LQSP: los comprobantes definidos por situación IVA en <code>SITIVA.CSP_DEF</code> y <code>SPU_DEF</code>, ver <code>Nucleo.GetComprobantes_SP</code>, <code>CapaNucleo/Nucleo.cs:4947-4956</code>). Los comprobantes que lo usan no pasan por WSFE: se imprimen con el CESP vigente.</p><p>Validaciones:</p><ul><li><strong>Superposición de rangos</strong> al cargar o editar un CESP: <code>ExisteCESPconFechas</code> (<code>clsFacturacionElectronica.cs:759-771</code>) y <code>ExisteCESPconFechasEXPT</code> (excluye el propio ID, <code>:773-785</code>). La condición detecta superposición solo si el inicio o el fin de un CESP existente cae dentro del rango nuevo; <strong>no detecta</strong> un CESP existente que contiene por completo al nuevo. Tampoco distingue CESP de CAEA. <code>CESPfechas</code> (<code>:787-799</code>) verifica si un ID tiene exactamente esas fechas.</li><li><strong>Facturación masiva</strong>: si algún servicio a facturar tiene <code>SERVICIO.LIQ_AFIP = 1</code>, tiene que existir un CESP con <code>FEC_INI ≤ hoy ≤ FEC_FIN</code> (<code>clsFacturacionMasiva.ValidarCESP</code>, <code>:275-288</code>). El usuario <code>SysAdmin</code> lo saltea.</li><li><strong>Anulaciones</strong>: misma regla para las facturas que se anulan (<code>clsAnulacionFacturas.ValidarCespLQSP</code>, <code>:1063-1077</code>).</li><li><strong>Al iniciar</strong>: aviso &quot;No se han encontrado CESP activos para la liquidación de servicios públicos&quot; (<code>Inicio_ProCoop.cs:1348-1351</code>).</li></ul><p>Observación: la asignación en <code>clsComprobante</code> exige <code>VTO_CESP ≥ hoy</code>, pero las validaciones de masiva y anulación miran solo <code>FEC_INI</code>/<code>FEC_FIN</code>.</p><h3 id="_4-3-caea" tabindex="-1">4.3 CAEA <a class="header-anchor" href="#_4-3-caea" aria-label="Permalink to &quot;4.3 CAEA&quot;">​</a></h3><ul><li><strong>Solicitud / consulta</strong> (<code>ConsultarCAEA(periodo, orden)</code>, <code>clsFacturacionElectronica.cs:1116-1135</code>): período <code>yyyyMM</code> y orden (1 = primera quincena, 2 = segunda). Primero intenta <code>FECAEAConsultar</code>; si no hay CAEA, llama a <code>FECAEASolicitar</code>. El alta en <code>CESPAFIP</code> la hace la pantalla, que no está en el código descompilado.</li><li><strong>Informe</strong> (<code>InformarCAEA(periodo, orden, CAEA)</code>, <code>:1188-1224</code>): toma las facturas con <code>CAE = &amp;lt;CAEA&gt;</code> y <code>COD_FAC ≠ &quot;P&quot;</code>, las agrupa por comprobante y punto de venta, las ordena y las informa en tandas de 100 con <code>AutorizaFacturas(agrupar, CAEA)</code>. Ese método convierte el request de CAE en <code>FECAEARequest</code> (agrega el CAEA a cada detalle) y llama a <code>FECAEARegInformativo</code> (<code>AutorizaFacturasCAEA</code>, <code>:1945-1979</code>). Lo informado queda con <code>COD_FAC = &quot;P&quot;</code>. Al final muestra la cantidad y el importe informado.</li><li><strong>No implementado</strong>: informar un CAEA sin movimiento (<code>FECAEASinMovimientoInformar</code> está en el proxy pero no se usa).</li></ul><h3 id="_4-4-cai" tabindex="-1">4.4 CAI <a class="header-anchor" href="#_4-4-cai" aria-label="Permalink to &quot;4.4 CAI&quot;">​</a></h3><p>Los comprobantes con CAI (talonarios preimpresos) toman <code>COMPPOS.CAI_ACTUAL</code> y <code>VTO_CAI</code>; no hay interacción con web services.</p><h2 id="_5-padron-de-contribuyentes" tabindex="-1">5. Padrón de contribuyentes <a class="header-anchor" href="#_5-padron-de-contribuyentes" aria-label="Permalink to &quot;5. Padrón de contribuyentes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Servicio</th><th>Método</th><th>Uso encontrado</th></tr></thead><tbody><tr><td><strong>Padrón A13</strong> (<code>ws_sr_padron_a13</code>, URL fija <code>aws.afip.gov.ar/sr-padron/webservices/personaServiceA13</code>)</td><td><code>GetCuilPersona(DNI)</code> → <code>getIdPersonaListByDocumento</code> (<code>clsFacturacionElectronica.cs:1137-1152</code>); <code>GetDatosPersona(cuil)</code> → <code>getPersona</code> (<code>:1154-1169</code>)</td><td>No se encontraron llamadas en el código descompilado. La respuesta trae apellido, nombre, razón social, domicilios, actividad principal, forma jurídica, estado de la clave, etc. (<code>ReglasNegocio.WSPA13/persona.cs</code>)</td></tr><tr><td><strong>Padrón PUC nivel 3</strong> (<code>WSPN3</code>, URL fija <code>aws.afip.gov.ar/padron-puc-ws/...</code>)</td><td><code>GetDatosContribuyente(cuit)</code> → <code>get(cuit, token, sign)</code>, devuelve un string (<code>:1171-1186</code>)</td><td>Validación del CUIT en el ABM de personas: si vuelve vacío muestra el error (<code>Configuracion/Configuracion.Forms/abm_Personas.cs:654-657</code>)</td></tr><tr><td><strong>Padrón A5 / constancia de inscripción</strong></td><td>—</td><td><strong>No existe</strong> en Procoop</td></tr></tbody></table><p>Además del web service, Procoop tiene un <strong>padrón offline</strong> en la tabla <code>EMPAFIP</code>, que se carga desde el archivo de condición tributaria que publica AFIP (<code>clsImportacionArchivos.cs:24-115</code>). Es un archivo de ancho fijo: CUIT (11), razón social (30), condición de IVA en las posiciones 44-45 y monotributo en las 46-47. La conversión es:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>si monotributo &lt;&gt; &quot;NI&quot; → &quot;MT&quot;</span></span>
<span class="line"><span>si no, según IVA: &quot;XN&quot; → &quot;EX&quot;, &quot;AN&quot; → &quot;NA&quot;, vacío → &quot;&quot;, otro → se copia (AC, NI, …)</span></span>
<span class="line"><span>COD_SIT = SITIVA cuyo COD_EMPAFIP coincide</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Se usa para cruzar la condición IVA de proveedores (<code>clsInformes_Compras.cs:4177-4230</code>, con opción de actualizarla) y de titulares (<code>clsInformes_Titulares.cs:1087</code>, <code>:1117</code>), y para buscar un CUIT (<code>Impuestos.busca_cuit_afip</code>, <code>Impuestos.cs:156-158</code>; control de proveedores con el parámetro 218).</p><p><code>ACTAFIP</code> es el catálogo de actividades AFIP. Se asigna al servicio del titular (<code>SERSOC.COD_ACT</code>, <code>clsInformes_Tecnica.cs:1906</code>) y se usa como filtro en cargos adicionales (<code>clsCargosAdicionales.cs:541</code>), pero <strong>no se informa a WSFE</strong>.</p><h2 id="_6-carpetas-in-out-modo-solo-factura-electronica" tabindex="-1">6. Carpetas IN/OUT (modo solo factura electrónica) <a class="header-anchor" href="#_6-carpetas-in-out-modo-solo-factura-electronica" aria-label="Permalink to &quot;6. Carpetas IN/OUT (modo solo factura electrónica)&quot;">​</a></h2><p><strong>Entrada</strong> — <code>ChequearCarpetaIN(path)</code> (<code>clsFacturacionElectronica.cs:1226-1317</code>); carpeta en el parámetro 2082:</p><ul><li>Lee todos los <code>*.csv</code> sin cabecera, con el separador del parámetro <strong>2497</strong> (por defecto <code>;</code>).</li><li>Cada fila tiene 46 columnas posicionales: tipo AFIP, punto de venta, número, fecha, importe, tipo y número de documento, concepto, servicio desde/hasta, moneda, cotización, no gravado, neto, exento, IVA, tributos, vencimiento de pago, nombre; hasta 3 alícuotas (base, importe, Id); hasta 3 tributos (base, alícuota, Id, descripción, importe); y opcionalmente marca de anulado, comprobante relacionado y fecha del relacionado (<code>:1237-1283</code>).</li><li>El comprobante relacionado son 16 caracteres: 4 de tipo, 4 de punto de venta y 8 de número. El CUIT del relacionado es el de la empresa (parámetro 519) para los códigos 203 y 208, y el del cliente en los demás casos (<code>:1411-1429</code>).</li><li>Si el comprobante ya existe pendiente y no se está procesando, lo reemplaza; si ya está autorizado, solo actualiza el archivo de origen (<code>:1430-1448</code>).</li><li>Si todo se graba bien, <strong>borra los archivos</strong> de la carpeta (<code>:1296-1304</code>).</li></ul><p><strong>Salida</strong> — <code>ChequearCarpetaOUT(path)</code> (<code>:1532-1600</code>); carpeta en el parámetro 2083:</p><ul><li>Por cada archivo de origen con novedades, escribe <code>&amp;lt;nombre&gt;_CAE.&amp;lt;ext&gt;</code> con 8 columnas: tipo, punto de venta, número, fecha, importe, CAE, vencimiento del CAE y error.</li><li>Marca el origen con el prefijo <code>EXP_</code> (exportado con CAE) o <code>ERR_</code> (exportado con error). Un <code>ERR_</code> se vuelve a exportar cuando se autoriza.</li></ul><p>Armado del request para estos comprobantes (<code>GetDetRequest(ELECTRONICA_FC)</code>, <code>:2629-2854</code>): toma del archivo los importes, la moneda y cotización, el concepto y las fechas. Si el documento no es numérico usa el CUIT genérico con <code>DocTipo = 80</code>. Para FCE aplica las mismas reglas de opcionales; en la 202 el CUIT asociado es el de la empresa (&quot;anulación MiPyME&quot;). Si no hay asociados que AFIP reconozca, informa <code>PeriodoAsoc</code>.</p><p>No se encontró en el código descompilado quién llama a <code>ChequearCarpetaIN</code>/<code>OUT</code> (probablemente un formulario que no está entre los binarios relevados).</p><h2 id="_7-mapeos-a-codigos-afip" tabindex="-1">7. Mapeos a códigos AFIP <a class="header-anchor" href="#_7-mapeos-a-codigos-afip" aria-label="Permalink to &quot;7. Mapeos a códigos AFIP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dato Procoop</th><th>Campo AFIP</th><th>Fuente</th></tr></thead><tbody><tr><td><code>COMPROB.COD_AFIP</code> (texto, se convierte a entero)</td><td><code>CbteTipo</code></td><td>Configurado a mano por comprobante; obligatorio para autorizar</td></tr><tr><td><code>COMPROB.TIPO_SIT = 1</code></td><td><code>DocTipo = 80</code> (CUIT)</td><td>Comprobantes &quot;A&quot;</td></tr><tr><td><code>DOCUMENT.COD_AFIP</code></td><td><code>DocTipo</code></td><td>Tipo de documento de la persona</td></tr><tr><td><code>SITIVA.AFIP_SIT</code></td><td><code>CondicionIVAReceptorId</code></td><td>0 = no se informa; 5 = consumidor final (forzado en reintentos); 6 = monotributo (<code>clsLibroIVA.Existe_SitIvaMonotributista</code>, <code>:2520-2523</code>)</td></tr><tr><td><code>SITIVA.AFIP_SIT</code> (formateado a 2 dígitos)</td><td>Código de condición en la exportación RG 3685 (<code>&quot;05&quot;</code> consumidor final, <code>&quot;07&quot;</code> no categorizado)</td><td><code>RG3685.cs:466</code>, <code>:500</code>, <code>:572-583</code> (corregido en segunda pasada: no es <code>SITIVA.COD_AFIP</code>)</td></tr><tr><td><code>SITIVA.COD_AFIP</code> (texto)</td><td>Solo se usa en la carátula del libro IVA agrupada por tipo, en RG 3349 y en compras</td><td><code>clsLibroIVA.cs:868</code>, <code>RG3349.cs:496</code>, <code>clsInformes_Compras.cs:1818</code></td></tr><tr><td><code>SITIVA.COD_EMPAFIP</code></td><td>Código del padrón offline (<code>AC</code>, <code>EX</code>, <code>MT</code>, <code>NA</code>, …)</td><td><code>EMPAFIP</code></td></tr><tr><td><code>ALI_IVA1</code> (%)</td><td><code>AlicIva.Id</code></td><td>Tabla fija <code>GetAlicuotasAfip</code></td></tr><tr><td><code>IMPUESTO.ORIGEN</code></td><td><code>Tributo.Id</code></td><td>Mapeo directo (ver dudas)</td></tr><tr><td>Tipo de ítem 1/2</td><td><code>Concepto</code> 1/2/3</td><td>Productos / servicios / ambos</td></tr></tbody></table><p>El código de barras del comprobante sigue el formato AFIP: CUIT + tipo (2) + punto de venta (4) + CAE + vencimiento (<code>Codigo_Varios_AFIP.cs:17</code>). El QR sigue el formato vigente (JSON en base64 sobre <code>https://www.afip.gob.ar/fe/qr/</code>, <code>clsFacturasImpresion.cs:948-980</code>).</p><h2 id="_8-libro-iva-ventas" tabindex="-1">8. Libro IVA Ventas <a class="header-anchor" href="#_8-libro-iva-ventas" aria-label="Permalink to &quot;8. Libro IVA Ventas&quot;">​</a></h2><h3 id="_8-1-criterios-y-tipos-de-informe" tabindex="-1">8.1 Criterios y tipos de informe <a class="header-anchor" href="#_8-1-criterios-y-tipos-de-informe" aria-label="Permalink to &quot;8.1 Criterios y tipos de informe&quot;">​</a></h3><p><code>clsLibroIVA</code> (<code>clsLibroIVA.cs:437-490</code>):</p><ul><li><strong>Criterio</strong> (<code>CriterioEmisionLibroIVA</code>): <ul><li><em>Facturado</em>.</li><li><em>Percibido</em>: para situaciones IVA con <code>SITIVA.PERCIBIDO</code>, se toma lo cobrado (<code>IT_PAGSO</code>) y lo refinanciado (<code>IT_RECCO</code>) en el período; las demás situaciones van por lo facturado (<code>:1124-1135</code>, <code>:1677-1730</code>). Es el criterio de devengamiento por cobro de los servicios públicos a no inscriptos.</li><li><em>Facturado y percibido</em>: lo no cobrado va por facturado, lo cobrado parcialmente se prorratea por <code>SALDO/TOTAL1</code>, y se suman los cobros del período de facturas del período y del mes siguiente (<code>:1053-1119</code>).</li><li><em>Cuotas facturadas vencidas</em>: prorratea cada factura por las cuotas de <code>TALONFAC</code> que vencen en el período (<code>:1270-1321</code>).</li></ul></li><li><strong>Fecha</strong>: de emisión o de vencimiento.</li><li><strong>Tipo de informe</strong> (<code>TipoInforme</code>): tradicional (con variante para libro rubricado), IVA por alícuota, neto por alícuota, neto e IVA por alícuota, agrupado por tipo de factura (usa <code>TIPO_FAC.COD_TPFC_GRUPO_IVA</code> para reagrupar, <code>:505-529</code>), por actividad, percepciones y consumos relevantes (RG 3349).</li></ul><h3 id="_8-2-reglas-de-armado" tabindex="-1">8.2 Reglas de armado <a class="header-anchor" href="#_8-2-reglas-de-armado" aria-label="Permalink to &quot;8.2 Reglas de armado&quot;">​</a></h3><p><code>GetDetalle</code> (<code>:901-1051</code>):</p><ul><li>Solo comprobantes de clase 0. Se excluyen los comprobantes por defecto de &quot;crédito/débito por prescripción de deuda&quot; y los cobros en planillas de caja de prescripción (<code>:906-919</code>).</li><li>Filtros por tipo de factura, comprobante, situación IVA, servicio, sucursal, interno o fiscal, solo créditos, localidad, grupo contable y titular activo. Facturación <em>mensual</em> = <code>FECHA ≠ VTO1</code>; <em>diaria</em> = <code>FECHA = VTO1</code> (<code>:971-982</code>).</li><li>Signo: positivo si <code>COMPROB.DEB_CRE = 1</code>, negativo en los créditos.</li><li>Por ítem de impuesto (tipo 4): subtipo 0 = no gravado / otros impuestos (por origen municipal, provincial, nacional, internos u otros); subtipo 1 = IVA alícuota 1 (con base <code>IMP_BI</code>); subtipo 2 = IVA alícuota 2; subtipo 4 = IVA 3 / percepción (<code>:1187-1268</code>).</li><li>Se agrega una fila de cabecera por comprobante con <code>ESTADO = &quot;A&quot;</code> (sin importes).</li><li>Parámetros: <strong>544</strong> (situación IVA &quot;no categorizado&quot;), <strong>2972</strong> &quot;Separar ítems financiados en libro de IVA ventas&quot;, <strong>3110</strong> &quot;Según lo percibido se informa el total del IVA del comprobante&quot;, <strong>2325</strong> (carátula por separado).</li></ul><p><strong>Carátula</strong> (<code>:768-855</code>): totales de débito y crédito, gravado e IVA por situación IVA y alícuota (<code>ALI_IVA_CF</code>). El crédito de las liquidaciones de servicios públicos se muestra aparte (columnas <code>_LQSP</code>). Se omiten las alícuotas en 0 y las filas sin gravado.</p><h3 id="_8-3-exportaciones-exportararchivos-2463-2518-tipoarchivos-cs" tabindex="-1">8.3 Exportaciones (<code>ExportarArchivos</code>, <code>:2463-2518</code>; <code>TipoArchivos.cs</code>) <a class="header-anchor" href="#_8-3-exportaciones-exportararchivos-2463-2518-tipoarchivos-cs" aria-label="Permalink to &quot;8.3 Exportaciones (\`ExportarArchivos\`, \`:2463-2518\`; \`TipoArchivos.cs\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Régimen</th><th>Archivo / clase</th></tr></thead><tbody><tr><td><code>Regimen_1361</code></td><td>RG 1361 – duplicados electrónicos</td><td><code>RG1361.cs</code></td></tr><tr><td><code>Regimen_2177</code></td><td>RG 2177</td><td>Lanza <code>NotImplementedException</code></td></tr><tr><td><code>Regimen_3349</code></td><td>RG 3349 – consumos relevantes</td><td><code>RG3349.cs</code></td></tr><tr><td><code>Regimen_3571</code> / <code>Regimen_49_2019</code></td><td>RG 3571 – rendición de comprobantes de servicios públicos (RCSP); la variante 49/2019 (RN 46/2019) incluye generadores</td><td><code>rg_3571_ddMMyyyy_hhmmss.txt</code> / <code>rg_46_2019_ddMMyyyy.txt</code> (<code>RG3571.cs:556-562</code>)</td></tr><tr><td><code>Regimen_3685</code></td><td>RG 3685 – régimen de información de compras y ventas (mismo diseño que importa el Libro IVA Digital)</td><td><code>REGINFO_CV_VENTAS_CBTE[_NO_INCLUIDOS]_yyyyMM.TXT</code> y <code>REGINFO_CV_VENTAS_ALICUOTAS…</code>; compras: <code>REGINFO_CV_COMPRAS_CBTE/ALICUOTAS…</code> (<code>RG3685.cs:268-361</code>)</td></tr><tr><td><code>PercepcionSICORE</code></td><td>Percepciones SICORE</td><td><code>PercepcionSICORE.cs</code></td></tr><tr><td><code>Circular_70_2021</code></td><td>ERSeP (Córdoba)</td><td><code>CIR7021.cs</code></td></tr></tbody></table><p>Reglas del archivo de ventas RG 3685 (<code>RG3685.cs:252-757</code>):</p><ul><li>Tipo con 3 dígitos; punto de venta con 5 (<code>00000</code> para los tipos 33, 99, 331 y 332); número con 20.</li><li>Comprador: código 80 con el CUIT del titular si tiene 11 dígitos y la condición no es <code>05</code> ni <code>07</code>; si no, el documento de la persona. Con código 99 y total de hasta $1000, número 0. El nombre se trunca a 20 caracteres y se completa a 30.</li><li>Moneda <code>PES</code>, tipo de cambio <code>0001000000</code>.</li><li>La fecha es la de vencimiento si el parámetro <strong>2692</strong> está activo y el comprobante se filtró por vencimiento.</li><li>Fecha de vencimiento de pago en ceros para los códigos 60, 61, 81, 82, 83, 201, 203, 206 y 208.</li><li>Importes negativos para los créditos de los códigos 17, 18, 60, 61 y 99.</li><li>Las percepciones de no categorizados se pasan a &quot;percepción de impuestos nacionales&quot; en el tipo 001.</li><li>Código de operación: <code>N</code> (no gravado), <code>E</code> (exento) o espacio.</li><li>Archivo de alícuotas: Id AFIP con 4 dígitos. Si hay alícuota pero el IVA es 0 y la base menor a $3, se informa <code>0003</code>.</li></ul><h2 id="_9-libro-iva-compras-y-libro-iva-digital" tabindex="-1">9. Libro IVA Compras y Libro IVA Digital <a class="header-anchor" href="#_9-libro-iva-compras-y-libro-iva-digital" aria-label="Permalink to &quot;9. Libro IVA Compras y Libro IVA Digital&quot;">​</a></h2><ul><li>La exportación del libro de compras (<code>RG3685.Exportar_Compra</code>, <code>:336-361</code>) parte de <code>IVACOM</code>. En compras se usa punto de venta <code>00000</code> para los tipos 033, 331 y 332, y el CUIT del proveedor como identificación del vendedor (<code>:775-781</code>).</li><li><strong>Comparación con AFIP</strong> (<code>clsLibroIVAdigital.cs</code>): se importa el Excel de &quot;Mis Comprobantes&quot; (emitidos o recibidos) desde la tercera fila (<code>Importar_ComprobantesAfip</code>, <code>:395-462</code>). Columnas: fecha, tipo (<code>&quot;&amp;lt;código&gt; - &amp;lt;descripción&gt;&quot;</code>), punto de venta, número desde, número hasta, tipo y número de documento, denominación, tipo de cambio (formato <code>en-US</code>), moneda, neto gravado, no gravado, exento, IVA y total. Si el tipo contiene &quot;Crédito&quot;, los importes se niegan.</li><li>Se cruza contra el libro de ventas (<code>Comparar_LibroVenta</code>, <code>:301-314</code>, con datos de <code>FACTURAS</code>) o de compras (<code>Comparar_LibroCompras</code>, <code>:526-539</code>, con <code>IVACOM</code> y <code>FPALIC_IVA</code>), por código AFIP + punto de venta y número dentro del rango (<code>Comparar_Comprobantes</code>, <code>:464-524</code>).</li><li>Resultado en tres informes: <ol><li>Comprobante inexistente en Procoop.</li><li>Comprobante inexistente en AFIP.</li><li>Diferencia de importe mayor a <strong>$1</strong> en neto, no gravado, exento, IVA o total.</li></ol></li><li>Si el total de Procoop es menor o igual a 0,03, todo se considera exento antes de comparar (<code>:492-498</code>).</li></ul><h2 id="_10-comprobantes-de-administracion-publica" tabindex="-1">10. Comprobantes de administración pública <a class="header-anchor" href="#_10-comprobantes-de-administracion-publica" aria-label="Permalink to &quot;10. Comprobantes de administración pública&quot;">​</a></h2><p><code>clsFacturacionVarios.cs:607-846</code> no tiene reglas impositivas ni llamadas a AFIP. Es un circuito de <strong>agrupación y cobro</strong> de las facturas de cuentas de organismos públicos (u otras cuentas que se liquidan en bloque):</p><ul><li><code>Get_ComprobantesAdmPublica</code> (<code>:692-803</code>) lista las facturas impagas (<code>PAGA = &quot;&quot;</code>) de un período o fecha de emisión a partir de los consumos (<code>CONS_SER</code>, tipo de energía vacío o <code>A</code>). Filtros: empresa postal, cuenta, titular, tipo de factura, servicio y rango de vencimiento. Agrupa por factura y servicio, con consumo total, medidor y domicilio del suministro.</li><li><code>Guardar_ComprobantesAdministracionPublica</code> (<code>:646-690</code>) reemplaza la selección del período o de la fecha de emisión en la tabla <code>COMPROBANTES_ADM</code> (<code>ID_FAC</code>, <code>COD_SER</code>, <code>PERIODO</code>, <code>FECHA</code>, <code>USU_REG</code>). Lo hace con SQL armado por concatenación.</li><li><code>Get_ComprobantesAdmPublica_Guardado</code> (<code>:805-846</code>) da la vista para cobrar en caja: facturas impagas guardadas (o todas), filtrables por período, grupo contable y &quot;recibos de empleados&quot; (cuentas asociadas a legajos en <code>SU_EMPLEADOS_SUMSOC</code>, para descuento por recibo de sueldo).</li><li><code>Existe_PeriodoAdministracionPublica</code> / <code>Existe_FechaEmisionAdministracionPublica</code> (<code>:614-622</code>) avisan si ya hay una selección guardada.</li></ul><h2 id="_11-resumen-de-parametros-busca-v2" tabindex="-1">11. Resumen de parámetros <code>Busca_V2_*</code> <a class="header-anchor" href="#_11-resumen-de-parametros-busca-v2" aria-label="Permalink to &quot;11. Resumen de parámetros \`Busca_V2_*\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N°</th><th>Tipo</th><th>Descripción</th><th>Dónde se usa</th></tr></thead><tbody><tr><td>519</td><td>Carácter</td><td>CUIT de la empresa</td><td>CUIT asociado en FCE, modo solo electrónica</td></tr><tr><td>544</td><td>Entero</td><td>Situación IVA &quot;no categorizado&quot;</td><td>Libro IVA</td></tr><tr><td>726</td><td>Lógica</td><td>Autorizar facturas en ARCA automáticamente</td><td>Agente</td></tr><tr><td>727</td><td>Lógica</td><td>Aguardar a que se registre en ARCA la factura</td><td>Venta, cobranza</td></tr><tr><td>2071</td><td>Carácter</td><td>Path del certificado ARCA</td><td>WSAA</td></tr><tr><td>2072</td><td>Carácter</td><td>URL WSAA</td><td>WSAA</td></tr><tr><td>2073</td><td>Carácter</td><td>URL WSFEv1</td><td>WSFE</td></tr><tr><td>2082 / 2083</td><td>Carácter</td><td>Carpetas de entrada / salida</td><td>Modo solo electrónica</td></tr><tr><td>2427</td><td>Numérica</td><td>Importe máximo para autorizar comprobantes electrónicos</td><td>Uso no encontrado</td></tr><tr><td>2431 / 2432</td><td>Carácter</td><td>CBU / alias para FCE MiPyME</td><td>Opcionales 2101/2102</td></tr><tr><td>2497</td><td>Carácter</td><td>Separador de los CSV (por defecto <code>;</code>)</td><td>Carpetas IN/OUT</td></tr><tr><td>2692</td><td>Lógica</td><td>Exportar IVA ventas digital según fecha del filtro</td><td>RG 3685</td></tr><tr><td>2712</td><td>Numérica</td><td>Importe máximo para enviar facturas por lote (por defecto 5000)</td><td>Agrupación</td></tr><tr><td>2769</td><td>Lógica</td><td>Bloquear comprobantes de cuentas con otros comprobantes bloqueados</td><td>Desbloqueo después del CAE</td></tr><tr><td>2780</td><td>Lógica</td><td>No utilizar CUIT genérico para registrar facturas</td><td>Receptor</td></tr><tr><td>2925</td><td>Carácter / fecha</td><td>Vencimiento del certificado ARCA (se completa solo)</td><td>Aviso al iniciar</td></tr><tr><td>2972</td><td>Lógica</td><td>Separar ítems financiados en libro IVA ventas</td><td>Libro IVA</td></tr><tr><td>3110</td><td>Lógica</td><td>Percibido: informar el total del IVA del comprobante</td><td>Libro IVA</td></tr><tr><td>217 / 218</td><td>Lógica</td><td>Compras: página de ARCA si el certificado del proveedor venció / controlar proveedores con la base de ARCA</td><td>Compras</td></tr><tr><td>2977</td><td>Lógica</td><td>Compras: consultar el ingreso de CAE/CAI al cargar una factura</td><td>Compras</td></tr></tbody></table><h2 id="_12-reglas-adicionales-segunda-pasada" tabindex="-1">12. Reglas adicionales (segunda pasada) <a class="header-anchor" href="#_12-reglas-adicionales-segunda-pasada" aria-label="Permalink to &quot;12. Reglas adicionales (segunda pasada)&quot;">​</a></h2><p>Revisión método por método de los proxies <code>ReglasNegocio.WSAA</code>, <code>WSFEV1</code>, <code>WSPA13</code>, <code>WSPN3</code> y de <code>clsFacturacionElectronica</code>, <code>clsLibroIVA</code>, <code>clsLibroIVAdigital</code> y <code>clsFacturacionVarios</code>. Solo se agrega lo que no estaba en las secciones 1 a 11.</p><h3 id="_12-1-mapeo-a-codigos-arca-tal-como-lo-implementa-el-codigo" tabindex="-1">12.1 Mapeo a códigos ARCA tal como lo implementa el código <a class="header-anchor" href="#_12-1-mapeo-a-codigos-arca-tal-como-lo-implementa-el-codigo" aria-label="Permalink to &quot;12.1 Mapeo a códigos ARCA tal como lo implementa el código&quot;">​</a></h3><p><strong>Cadena situación IVA → comprobante → <code>CbteTipo</code>.</strong> El código ARCA del comprobante <strong>no está fijo en el código</strong>: sale de <code>COMPROB.COD_AFIP</code>, que se configura a mano por comprobante (no hay datos semilla de <code>COD_AFIP</code> para <code>COMPROB</code> en <code>CapaNucleo/clsDefault.cs</code>). El comprobante interno lo elige <code>clsComprobante.GetComprobanteOperacion</code> (<code>clsComprobante.cs:192-264</code>, detallado en el documento 02, §3.2): servicios con <code>LIQ_AFIP = 1</code> → <code>SITIVA.SPU_DEF</code> / <code>CSP_DEF</code>; comprobante del servicio (<code>COM_FAC</code> / <code>COM_CRE</code>); comprobante del tipo de factura; FCE MiPyME (<code>SITIVA.COM_*_MIPYME</code> si la cuenta es MiPyME y el importe supera el parámetro 2515); y por último <code>SITIVA.COM_DEF</code> / <code>CRE_DEF</code> / <code>DEB_DEF</code>. Lo que sí está fijo en el código es el <strong>comportamiento según el código ARCA</strong> ya configurado:</p><table tabindex="0"><thead><tr><th>Código(s) ARCA (<code>CbteTipo</code>)</th><th>Comportamiento fijo en Procoop</th><th>Cita</th></tr></thead><tbody><tr><td>6, 7, 8, 9, 10, 11, 12, 13, 15, 35, 40, 49, 61, 64</td><td>Agrupables en lote (<code>CbteDesde..CbteHasta</code>, receptor 99/0), en ambos modos</td><td><code>clsFacturacionElectronica.cs:1992-1996</code>, <code>:2208-2212</code></td></tr><tr><td>11, 13 (C)</td><td>El exento se suma al neto y <code>ImpOpEx = 0</code> (solo modo completo)</td><td><code>:2477-2481</code></td></tr><tr><td>2, 3, 7, 8, 11, 12, 13, 202, 203, 207, 208, 212, 213</td><td>Informa <code>CbtesAsoc</code> o <code>PeriodoAsoc</code> (modo completo)</td><td><code>:2551-2621</code></td></tr><tr><td>2, 3, 7, 8, 202, 203, 207, 208, 212, 213</td><td>Ídem en modo solo electrónica (no incluye 11, 12, 13)</td><td><code>:2812-2847</code></td></tr><tr><td>2, 3, 7, 8</td><td><code>PeriodoAsoc</code> obligatorio con el período de la nota si no hay asociados</td><td><code>:2602-2620</code></td></tr><tr><td>201, 202, 203, 206, 207, 208, 211, 212, 213 (FCE)</td><td><code>FchVtoPago = VTO1</code>, anulado en créditos (<code>DEB_CRE = 2</code>) y en 202</td><td><code>:2436-2442</code></td></tr><tr><td>201, 206, 211 (FCE sin ND/NC)</td><td>Opcionales 2101 (CBU, parámetro 2431) y 2102 (alias, 2432). En modo completo se envían aunque estén vacíos; en modo solo electrónica solo si tienen valor</td><td><code>:2443-2455</code>, <code>:2692-2710</code></td></tr><tr><td>201, 206, 211</td><td>Opcional 27 = <code>SCA</code></td><td><code>:2456-2463</code></td></tr><tr><td>203, 208, 213</td><td>Opcional 22 (anulación <code>S</code>/<code>N</code>)</td><td><code>:2561-2569</code></td></tr><tr><td>202, 203, 208, 213 (solo electrónica)</td><td>Opcional 22 desde la columna &quot;anulado&quot; del CSV; <code>FchVtoPago</code> nulo; en 202 o anulación <code>S</code>, el CUIT asociado es el de la empresa</td><td><code>:2797-2811</code></td></tr><tr><td>33, 99, 331, 332 / 60, 61, 81, 82, 83, 201, 203, 206, 208 / 17, 18, 60, 61, 99</td><td>Solo en la exportación RG 3685: punto de venta <code>00000</code> / vencimiento de pago en ceros / importes negativos en créditos</td><td>§8.3</td></tr></tbody></table><p><strong>Receptor (<code>DocTipo</code>, <code>CondicionIVAReceptorId</code>)</strong></p><table tabindex="0"><thead><tr><th>Dato Procoop</th><th>Código ARCA enviado</th><th>Observación</th></tr></thead><tbody><tr><td><code>COMPROB.TIPO_SIT = 1</code></td><td><code>DocTipo 80</code>, <code>DocNro = SOCIOS.CUIT</code></td><td>Con DNI de 8 dígitos genera el CUIT (§3.4)</td></tr><tr><td><code>DOCUMENT.COD_AFIP</code></td><td><code>DocTipo</code></td><td>Semilla: Desconocido 99, DNI 96, LE 89, LC 90, Pasaporte 94, Cédula 91, CUIL 86, Interno 99, CUIT 80 (<code>clsDefault.cs:885</code>). Coinciden con la tabla de ARCA</td></tr><tr><td><code>SITIVA.AFIP_SIT ≠ 0</code></td><td><code>CondicionIVAReceptorId</code></td><td>Se copia tal cual (<code>clsFacturacionElectronica.cs:2424-2429</code>); 0 no se informa</td></tr><tr><td>Reintento por 10242/10243</td><td><code>CondicionIVAReceptorId = 5</code></td><td>Fuerza consumidor final (<code>:2028-2032</code>)</td></tr></tbody></table><p>Valores semilla de <code>SITIVA.AFIP_SIT</code> en una base nueva (<code>clsDefault.cs:885</code>): responsable inscripto 1, responsable no inscripto 2, no responsable 3, <strong>consumidor final 4</strong>, <strong>exento 5</strong>, monotributo 6, no categorizado 7. En la tabla vigente de <code>FEParamGetCondicionIvaReceptor</code>, 4 es <strong>sujeto exento</strong> y 5 es <strong>consumidor final</strong>, y 2 y 3 ya no existen. O sea, con los valores semilla Procoop informa a los consumidores finales como exentos y a los exentos como consumidores finales. La propia exportación RG 3685 supone la convención de ARCA (trata <code>AFIP_SIT = 05</code> como consumidor final, <code>RG3685.cs:572</code>, <code>:583</code>), así que el semilla y el código no son coherentes entre sí. <strong>[VERIFICAR]</strong> los <code>AFIP_SIT</code> cargados en la base de Laguna Larga: si se corrigieron a mano, no hay problema.</p><p><strong>Alícuotas de IVA (<code>AlicIva.Id</code>)</strong></p><table tabindex="0"><thead><tr><th>% del ítem (<code>ITEMSFAC.POR_IMP</code>)</th><th>Modo completo</th><th>Modo solo electrónica</th><th>Libro IVA (columna)</th></tr></thead><tbody><tr><td>0</td><td>No se informa (la tabla se cruza sin el 0 %)</td><td>Id 3, salvo que <code>ORIGEN</code> (archivo de origen) sea nulo</td><td>Exento / no gravado</td></tr><tr><td>2,5</td><td>9</td><td>Lo trae el CSV</td><td>&quot;Otros&quot;</td></tr><tr><td>5</td><td>8</td><td>Lo trae el CSV</td><td>&quot;Otros&quot;</td></tr><tr><td>10,5</td><td>4</td><td>Lo trae el CSV</td><td>10,5</td></tr><tr><td>21</td><td>5</td><td>Lo trae el CSV</td><td>21</td></tr><tr><td>27</td><td>6</td><td>Lo trae el CSV</td><td>27</td></tr><tr><td>Cualquier otro</td><td><strong>Se descarta en silencio</strong></td><td>Se descarta si no está en la tabla</td><td>&quot;Otros&quot;</td></tr></tbody></table><p>Fuentes: <code>clsFacturacionElectronica.cs:2482-2515</code>, <code>:2737-2767</code>, <code>:2856-2891</code>; <code>clsLibroIVA.cs:586-595</code>. Consecuencia: un ítem con un porcentaje que no esté en la tabla fija suma al total de la factura pero no a <code>ImpIVA</code>, el detalle no cierra y ARCA lo rechaza. La regla &quot;las que quedan en cero van al Id 3&quot; (§3.4) prácticamente no se da, porque antes se descartan las que tienen base e importe menores a 0,01 y el 0 % ni siquiera entra al cruce. <strong>[VERIFICAR]</strong> que todos los <code>POR_IMP</code> de IVA configurados en la cooperativa estén en la tabla. En modo solo electrónica las alícuotas solo se informan si <code>ImpNeto ≠ 0</code>, y se descartan las de importe 0 que no sean Id 3 (<code>:2737</code>, <code>:2765</code>).</p><h3 id="_12-2-tributos-conclusion-sobre-el-mapeo-de-id" tabindex="-1">12.2 Tributos: conclusión sobre el mapeo de Id <a class="header-anchor" href="#_12-2-tributos-conclusion-sobre-el-mapeo-de-id" aria-label="Permalink to &quot;12.2 Tributos: conclusión sobre el mapeo de Id&quot;">​</a></h3><p>Se verificó la duda abierta 1:</p><ul><li>El enum que da significado a <code>IMPUESTO.ORIGEN</code> es <code>clsLibroIVA.OrigenImpuesto</code> (<code>clsLibroIVA.cs:475-482</code>): 0 otros, 1 municipal, 2 provincial, 3 nacional, 4 internos. Se usa igual en el libro IVA (<code>:1263-1267</code>, <code>:1501-1505</code>), en RG 1361 (<code>RG1361.cs:270-272</code>), en RG 3685 por ítems (<code>RG3685_ITEMS.cs:429-433</code>) y en RG 3685 (<code>RG3685.cs:613-617</code>; ahí las percepciones de no categorizados se pasan a <code>OrigenImpuesto.Nacional</code>). No hay ninguna pantalla ni dato semilla que use otra convención.</li><li><code>GetDetRequest</code> envía <code>Tributo.Id = ORIGEN</code> (subtipo 0) o 3 fijo (subtipo 4 = <code>Percepcion_IVA</code> según <code>CapaNucleo/Facturacion_SubTipos_ImpuestoIVA.cs</code>) (<code>clsFacturacionElectronica.cs:2516-2534</code>).</li></ul><table tabindex="0"><thead><tr><th><code>ORIGEN</code> en Procoop</th><th>Subtipo</th><th>Qué envía</th><th>Significado en ARCA (<code>FEParamGetTiposTributos</code>)</th><th>¿Correcto?</th></tr></thead><tbody><tr><td>0 otros</td><td>0</td><td>Va a <code>ImpTotConc</code> (no gravado), no como tributo</td><td>—</td><td>Discutible: un impuesto &quot;otro&quot; se informa como concepto no gravado</td></tr><tr><td>0 otros</td><td>4</td><td>Nada: ni IVA, ni tributo, ni no gravado</td><td>—</td><td>No: el importe solo cierra si la diferencia es menor a 0,03</td></tr><tr><td>1 municipal</td><td>0</td><td>Id 1</td><td>Impuestos nacionales</td><td><strong>No</strong> (debería ser 3)</td></tr><tr><td>2 provincial</td><td>0</td><td>Id 2</td><td>Impuestos provinciales</td><td>Sí</td></tr><tr><td>3 nacional</td><td>0</td><td>Id 3</td><td>Impuestos municipales</td><td><strong>No</strong> (debería ser 1)</td></tr><tr><td>4 internos</td><td>0</td><td>Id 4</td><td>Impuestos internos</td><td>Sí</td></tr><tr><td>1 a 4</td><td>4 (percepción IVA)</td><td>Id 3</td><td>Impuestos municipales</td><td><strong>No</strong> (debería ser 6, percepción de IVA, o 13 si el receptor es no categorizado)</td></tr></tbody></table><p>Nunca se envían los Id 5 (ingresos brutos), 7 (percepción de IIBB), 8 (percepciones municipales), 9 (otras percepciones) ni 99 (otros). Además, la segunda agrupación es solo por Id (<code>:2539-2548</code>): una percepción y un impuesto nacional terminan fusionados en un único tributo Id 3, con la alícuota y la descripción del primero.</p><p><strong>Conclusión</strong>: es un defecto del código, no una convención distinta de los datos. Si una base tuviera los orígenes &quot;invertidos&quot; para que el WSFE informe bien, el libro IVA y las exportaciones RG 1361 / RG 3685 mostrarían mal los impuestos municipales y nacionales. ARCA no rechaza estos comprobantes porque solo valida que el Id exista y que la suma coincida con <code>ImpTrib</code>; el error es de clasificación informativa y se ve en &quot;Mis Comprobantes&quot; y en el Libro IVA Digital del receptor. En el modo solo electrónica el Id lo trae el CSV (<code>TIPO_TRIB</code>), así que ahí el mapeo es responsabilidad del sistema de origen (<code>:2768-2795</code>). <strong>[VERIFICAR]</strong> los <code>IMPUESTO.ORIGEN</code> y subtipos de los impuestos que factura Laguna Larga: si solo tiene provinciales e internos sin percepciones de IVA, el impacto es nulo. Para GoodApps vale la recomendación 7.</p><h3 id="_12-3-clsfacturacionelectronica-metodos-y-detalles-no-documentados" tabindex="-1">12.3 <code>clsFacturacionElectronica</code>: métodos y detalles no documentados <a class="header-anchor" href="#_12-3-clsfacturacionelectronica-metodos-y-detalles-no-documentados" aria-label="Permalink to &quot;12.3 \`clsFacturacionElectronica\`: métodos y detalles no documentados&quot;">​</a></h3><ul><li><strong><code>Get_ComprobantesRelacionados(id_factura)</code></strong> (<code>:1464-1530</code>), solo modo solo electrónica: devuelve los comprobantes relacionados de una fila de <code>ELECTRONICA_FC</code>. Junta las filas propias de <code>ELECTRONICA_RELCOMP</code> y, si el campo <code>COMPROB_RELACION</code> (16 caracteres: tipo, punto de venta y número) tiene valor, también las filas de <code>ELECTRONICA_RELCOMP</code> de <strong>cualquier</strong> comprobante que apunten a ese mismo relacionado (mismo tipo, punto de venta y número), sin repetir. Describe cada uno con el texto de <code>FEParamGetTiposCbte</code>. Usa el ticket en memoria <strong>sin llamar a <code>CargarTicket</code></strong>: si todavía no se cargó, la excepción se registra y devuelve la lista vacía.</li><li><strong><code>ObtieneCertificadoDesdeArchivo</code></strong> (<code>:438-450</code>): ante cualquier error al importar el certificado lanza una excepción con la ruta del archivo y la traza, que se muestra como &quot;Error FIRMANDO el LoginTicketRequest&quot;. <code>FirmaBytesMensaje</code> (<code>:421-436</code>) antepone &quot;***Error al firmar&quot;.</li><li><strong><code>ImportarElectronicaFC</code></strong> (privado, <code>:1318-1462</code>): graba hasta 3 alícuotas y 3 tributos por comprobante, y solo si el tipo (<code>TIPOIVA*</code>, <code>TIPO_TRIB*</code>) es distinto de 0. El campo &quot;anulado&quot; se guarda recortado y en mayúsculas. Todo el lote se graba en un único <code>SubmitChanges</code>; si falla, no se borra ningún CSV.</li><li><strong><code>AutorizaElectronicas</code></strong> (privado, <code>:2201-2347</code>): a diferencia del modo completo, <strong>no maneja</strong> los errores 10242/10243 (no reintenta con consumidor final) y ante el 10040 borra las relaciones del comprobante y no le escribe ningún error. Las observaciones de un comprobante aprobado también se toman del primer detalle de la respuesta.</li><li><strong>Respuesta de <code>ConsultarInconsistencias</code></strong> (privados, <code>:1724-1800</code>): si difieren el CAE y el importe, el mensaje del importe <strong>reemplaza</strong> al del CAE en lugar de sumarse (<code>:1738</code>, <code>:1771</code>). El texto rotula el total local como &quot;Total en PWIF&quot;.</li><li><strong><code>ConsultaPreviaAutorizar</code></strong> (<code>:1812-1825</code>) arma el detalle con código ARCA 0: la vista previa no aplica las reglas que dependen del código (C, FCE, asociados).</li><li><strong><code>ConsultarCAE(tipo, punto de venta, número)</code></strong> público (<code>:1802-1810</code>) también usa el ticket en memoria sin cargarlo.</li><li><strong>Factura C con total muy bajo</strong>: el ajuste &quot;total ≤ 0,03 → todo exento&quot; y el de cierre &quot;diferencia &lt; 0,03 al exento&quot; (<code>:2057-2068</code>) se aplican <strong>después</strong> de pasar el exento al neto en los códigos 11 y 13, así que pueden dejar <code>ImpOpEx ≠ 0</code> en una factura C, cosa que ARCA no acepta para la clase C. Tampoco anulan <code>ImpTrib</code> ni <code>ImpTotConc</code> cuando fuerzan todo a exento. <strong>[VERIFICAR]</strong> solo si la cooperativa emite comprobantes C.</li><li><strong>CAEA</strong>: <code>AutorizaFacturasCAEA</code> (<code>:1945-1979</code>) copia el detalle de CAE al de CAEA por reflexión, así que <strong>nunca informa <code>CbteFchHsGen</code></strong> (fecha y hora de generación, campo exclusivo de <code>FECAEADetRequest.cs:32</code>).</li></ul><h3 id="_12-4-proxies-soap-que-se-usa-realmente" tabindex="-1">12.4 Proxies SOAP: qué se usa realmente <a class="header-anchor" href="#_12-4-proxies-soap-que-se-usa-realmente" aria-label="Permalink to &quot;12.4 Proxies SOAP: qué se usa realmente&quot;">​</a></h3><p>Todos los proxies son clases generadas por <code>wsdl.exe</code> (<code>SoapHttpClientProtocol</code>). Procoop llama siempre a las variantes <strong>sincrónicas</strong>; ninguna variante <code>*Async</code>, <code>CancelAsync</code> ni evento <code>*Completed</code> se usa.</p><p><strong>WSAA</strong> (<code>ReglasNegocio.WSAA/LoginCMSService.cs</code>): solo <code>loginCms(CMS en base64)</code> (<code>:71-74</code>), con la URL del parámetro 2072 (<code>clsFacturacionElectronica.cs:352-355</code>). El constructor apunta por defecto a homologación (<code>:55-67</code>).</p><p><strong>WSFEv1</strong> (<code>ReglasNegocio.WSFEV1/Service.cs</code>):</p><table tabindex="0"><thead><tr><th>Operación</th><th>Desde</th><th>Campos de entrada usados</th><th>Campos de respuesta usados</th></tr></thead><tbody><tr><td><code>FECAESolicitar</code> (<code>:158</code>)</td><td><code>AutorizaFacturas</code>, <code>AutorizaElectronicas</code></td><td>Cabecera: <code>CantReg</code>, <code>CbteTipo</code>, <code>PtoVta</code>. Detalle: <code>Concepto</code>, <code>DocTipo</code>, <code>DocNro</code>, <code>CbteDesde</code>, <code>CbteHasta</code>, <code>CbteFch</code>, <code>ImpTotal</code>, <code>ImpTotConc</code>, <code>ImpNeto</code>, <code>ImpOpEx</code>, <code>ImpIVA</code>, <code>ImpTrib</code>, <code>FchServDesde</code>, <code>FchServHasta</code>, <code>FchVtoPago</code>, <code>MonId</code>, <code>MonCotiz</code>, <code>CondicionIVAReceptorId</code>, <code>Iva[]</code> (<code>Id</code>, <code>BaseImp</code>, <code>Importe</code>), <code>Tributos[]</code> (<code>Id</code>, <code>Desc</code>, <code>BaseImp</code>, <code>Alic</code>, <code>Importe</code>), <code>CbtesAsoc[]</code> (<code>Tipo</code>, <code>PtoVta</code>, <code>Nro</code>, <code>Cuit</code>, <code>CbteFch</code>), <code>PeriodoAsoc</code>, <code>Opcionales[]</code> (<code>Id</code>, <code>Valor</code>)</td><td><code>FeCabResp.Resultado</code>; <code>FeDetResp[]</code>: <code>CbteDesde</code>, <code>CbteHasta</code>, <code>Resultado</code>, <code>CAE</code>, <code>CAEFchVto</code>, <code>Observaciones[]</code> (<code>Code</code>, <code>Msg</code>); <code>Errors[]</code> (<code>Code</code>, <code>Msg</code>)</td></tr><tr><td><code>FECAEARegInformativo</code> (<code>:303</code>)</td><td><code>AutorizaFacturasCAEA</code></td><td>Ídem más <code>CAEA</code></td><td>Ídem, con <code>CAEA</code> en lugar de <code>CAE</code></td></tr><tr><td><code>FECompConsultar</code> (<code>:274</code>)</td><td>Consultas, inconsistencias, error 10016</td><td><code>CbteTipo</code>, <code>PtoVta</code>, <code>CbteNro</code></td><td><code>ResultGet</code>: <code>Resultado</code>, <code>CodAutorizacion</code>, <code>FchVto</code>, <code>ImpTotal</code>, <code>CbteDesde</code>, <code>CbteHasta</code>; <code>Errors</code></td></tr><tr><td><code>FECompUltimoAutorizado</code> (<code>:245</code>)</td><td><code>ConsultarNumCom</code></td><td><code>PtoVta</code>, <code>CbteTipo</code></td><td><code>CbteNro</code>, <code>Errors</code></td></tr><tr><td><code>FECAEAConsultar</code> / <code>FECAEASolicitar</code> (<code>:419</code>, <code>:332</code>)</td><td><code>ConsultarCAEA</code></td><td>Período <code>yyyyMM</code>, orden</td><td><code>ResultGet</code> completo (lo usa la pantalla)</td></tr><tr><td><code>FEParamGetPtosVenta</code> (<code>:622</code>)</td><td><code>ConsultarPuntosVenta</code></td><td>—</td><td><code>Nro</code>, <code>Bloqueado = &quot;N&quot;</code>, <code>FchBaja = &quot;NULL&quot;</code></td></tr><tr><td><code>FEParamGetTiposCbte</code>, <code>TiposMonedas</code>, <code>TiposIva</code>, <code>TiposConcepto</code>, <code>TiposTributos</code>, <code>TiposDoc</code>, <code>TiposOpcional</code>, <code>TiposPaises</code>, <code>CondicionIvaReceptor</code></td><td><code>ObtenerTabla</code>, <code>lstComprobantes</code>, <code>Get_ComprobantesRelacionados</code></td><td><code>FEParamGetCondicionIvaReceptor</code> se llama con clase de comprobante nula (todas)</td><td><code>Id</code>, <code>Desc</code> (y vigencia en opcionales)</td></tr></tbody></table><p>Campos del contrato que <strong>nunca se completan</strong>: <code>CanMisMonExt</code> (<code>FEDetRequest.cs:292</code>), <code>Compradores</code>, <code>Actividades</code> y <code>CbteFchHsGen</code>. <code>CanMisMonExt</code> solo importa con moneda extranjera, que únicamente puede llegar por el CSV del modo solo electrónica (<strong>[VERIFICAR]</strong> si la cooperativa usa ese modo con moneda distinta de <code>PES</code>). Operaciones generadas pero sin uso: <code>FEDummy</code>, <code>FECompTotXRequest</code>, <code>FEParamGetCotizacion</code>, <code>FEParamGetActividades</code>, <code>FECAEASinMovimientoConsultar</code> y <code>FECAEASinMovimientoInformar</code>.</p><p><strong>Padrón A13</strong> (<code>ReglasNegocio.WSPA13/PersonaServiceA13.cs</code>): <code>getIdPersonaListByDocumento(token, sign, cuitRepresentada, documento)</code> (<code>:110</code>) y <code>getPersona(token, sign, cuitRepresentada, idPersona)</code> (<code>:140</code>); el CUIT representado es el que se leyó del ticket. <code>dummy</code> no se usa.</p><p><strong>Padrón PUC nivel 3</strong> (<code>ReglasNegocio.WSPN3/ContribuyenteNivel3SelectServiceImplService.cs</code>): solo <code>get(cuit, token, sign)</code> (<code>:74</code>), que devuelve un texto sin tipar; no se informa el CUIT representado. Es el único cliente sin timeout explícito (<code>clsFacturacionElectronica.cs:509-514</code>). <code>dummy</code> no se usa.</p><p>Métodos sin regla de negocio (proxies, revisados): <code>LoginCMSService.loginCmsAsync</code> (2), <code>LoginCMSService.CancelAsync</code>; en <code>Service</code>, todas las variantes <code>*Async</code> de <code>FECAESolicitar</code>, <code>FECompTotXRequest</code>, <code>FEDummy</code>, <code>FECompUltimoAutorizado</code>, <code>FECompConsultar</code>, <code>FECAEARegInformativo</code>, <code>FECAEASolicitar</code>, <code>FECAEASinMovimientoConsultar</code>, <code>FECAEASinMovimientoInformar</code>, <code>FECAEAConsultar</code>, <code>FEParamGetCotizacion</code>, <code>FEParamGetTiposTributos</code>, <code>FEParamGetTiposMonedas</code>, <code>FEParamGetTiposIva</code>, <code>FEParamGetTiposOpcional</code>, <code>FEParamGetTiposConcepto</code>, <code>FEParamGetPtosVenta</code>, <code>FEParamGetTiposCbte</code>, <code>FEParamGetCondicionIvaReceptor</code>, <code>FEParamGetTiposDoc</code>, <code>FEParamGetTiposPaises</code>, <code>FEParamGetActividades</code>, más <code>Service.CancelAsync</code> y las sincrónicas <code>FEParamGetTiposMonedas</code>, <code>FEParamGetTiposIva</code>, <code>FEParamGetTiposOpcional</code>, <code>FEParamGetTiposConcepto</code>, <code>FEParamGetTiposDoc</code> y <code>FEParamGetTiposPaises</code> (solo descargan tablas); <code>PersonaServiceA13.dummy</code>, <code>dummyAsync</code> (2), <code>getIdPersonaListByDocumentoAsync</code> (2), <code>getPersonaAsync</code> (2), <code>CancelAsync</code>; <code>ContribuyenteNivel3SelectServiceImplService.getAsync</code> (2), <code>dummy</code>, <code>dummyAsync</code> (2), <code>CancelAsync</code>.</p><h3 id="_12-5-clslibroiva-armado-de-informes" tabindex="-1">12.5 <code>clsLibroIVA</code>: armado de informes <a class="header-anchor" href="#_12-5-clslibroiva-armado-de-informes" aria-label="Permalink to &quot;12.5 \`clsLibroIVA\`: armado de informes&quot;">​</a></h3><ul><li><strong><code>Get_Reporte(filtros)</code></strong> (<code>:491-503</code>): elige el diseño de reporte según el tipo de informe (el tradicional tiene variante &quot;rubricado&quot;) y la carátula (<code>Facturacion_LibroIVA_Caratula_Tipo</code> solo para el agrupado por tipo de factura). En el agrupado por tipo, antes reasigna el tipo de factura según <code>TIPO_FAC.COD_TPFC_GRUPO_IVA</code> (<code>ActualizarTiposSegunGrupo</code>, <code>:505-529</code>).</li><li><strong><code>Get_ReporteDatasource(detalle, filtros, extra)</code></strong> (<code>:531-756</code>): primero arma la lista de comprobantes (con los IDs de ítems financiados y de pagos) que después usan las exportaciones. Luego agrupa según el tipo de informe: <ul><li><em>Tradicional</em>: por comprobante, con no gravado, exento, gravado, IVA 1/2/3 y total, más la condición fiscal (<code>RES_SIT</code>).</li><li><em>Por alícuota</em> (IVA, neto o ambos) y <em>agrupado por tipo</em>: separa IVA y gravado en columnas <strong>10,5 %, 21 %, 27 % y &quot;otros&quot;</strong> (cualquier otro porcentaje, incluidos 2,5 % y 5 %), y marca intereses por vencimiento y facturación diaria.</li><li><em>Por actividad</em>: agrupa por actividad del rubro del producto o servicio (&quot;OTROS&quot; si no tiene) y situación IVA, con las mismas columnas por alícuota.</li><li><em>Percepciones</em>: por cuenta, CUIT, nombre, domicilio y comprobante; el importe de percepción es <strong>solo el IVA 3</strong> (subtipo 4). Las percepciones de ingresos brutos u otros tributos no aparecen.</li><li><em>Consumos relevantes</em>: delega en <code>RG3349.Get_Detalle_Exportar</code>. Hay un segundo bloque idéntico inalcanzable (<code>:732-754</code>).</li></ul></li><li><strong><code>Get_ReporteCaratula(detalle, tipo)</code></strong> (<code>:757-766</code>): sin carátula para consumos relevantes; para el agrupado por tipo, totales por situación IVA, tipo de factura, débito/crédito, comprobante y <code>SITIVA.COD_AFIP</code> (<code>:857-899</code>); en los demás, la carátula general de §8.2. En la general, la descripción de la alícuota sale de <code>ALI_IVA_CF</code> cruzando la situación IVA con <code>POR_IVA</code> (IVA 1), <code>POR_IVA2</code> (IVA 2) o <code>PER_IVA</code> (percepción).</li><li><strong><code>Info_Archivo.GetComprobantesFiltroVto</code></strong> (<code>:417-426</code>): devuelve los comprobantes marcados con <code>FiltradoXVto</code>, que alimentan la regla del parámetro 2692 en RG 3685 (<code>RG3685.cs:674</code>). En todo el código descompilado <strong>nadie asigna <code>FiltradoXVto = true</code></strong>, así que la lista siempre está vacía y el parámetro 2692 no tiene efecto. <strong>[VERIFICAR]</strong> si 2692 está activo en la base (si lo está, el usuario espera un comportamiento que no ocurre).</li></ul><p>Métodos sin regla de negocio: <code>Get_ComboOrden</code> (no ordenar; tipo y número; fecha, tipo y número; fecha y número), <code>Get_ComboFacturacion</code> (todos / solo mensual / solo diaria, cuyo criterio está en §8.2).</p><h3 id="_12-6-clslibroivadigital-informes-y-detalles-de-la-comparacion" tabindex="-1">12.6 <code>clsLibroIVAdigital</code>: informes y detalles de la comparación <a class="header-anchor" href="#_12-6-clslibroivadigital-informes-y-detalles-de-la-comparacion" aria-label="Permalink to &quot;12.6 \`clsLibroIVAdigital\`: informes y detalles de la comparación&quot;">​</a></h3><ul><li><strong>Informes</strong> (<code>Get_Informe_ComprobantesNoAfip</code>, <code>Get_Informe_ComprobantesNoProcoop</code>, <code>Get_Informe_ComprobantesDiferencia</code>, <code>:188-299</code>), cada uno con una variante para el libro de ventas y otra para el de compras: <ul><li><em>No registrados en ARCA</em> (<code>TipoError.ComprobanteInexistenteAFIP</code>): comprobantes de Procoop con fecha, vencimiento, CUIT, cuenta, CAE, denominación e importes de Procoop, incluida la percepción.</li><li><em>No registrados en Procoop</em>: filas del archivo de ARCA con sus importes.</li><li><em>Con diferencias</em>: importes de ambos lados.</li><li>Parámetros del reporte: tipo de fecha y rango. En compras el tipo de fecha se fija en &quot;Emisión&quot;.</li></ul></li><li><strong>Total de Procoop en ventas</strong> (<code>Get_ComprobantesVenta</code>, <code>:316-393</code>): no se toma <code>TOTAL1</code>; se recalcula como exento + gravado + no gravado + <strong>IVA 1</strong> + IVA 3 (percepción). El <strong>IVA 2</strong> (subtipo 2) no se suma ni se compara, así que un comprobante con dos alícuotas aparece con diferencia de IVA y de total. <strong>[VERIFICAR]</strong> si la cooperativa factura ítems con alícuota 2. Se excluyen los comprobantes internos. Si algún <code>COMPROB.COD_AFIP</code> no es numérico, falla todo el lote y devuelve &quot;Ha ocurrido una inconsistencia al consultar los comprobantes&quot;.</li><li><strong>Compras</strong> (<code>Get_ComprobantesCompra</code>, <code>:541-615</code>): gravado, no gravado y exento de <code>IVACOM</code>; IVA = suma de <code>FPALIC_IVA.IMP_IVA</code> <strong>sin aplicar el signo</strong> de la nota de crédito, mientras que el total sí se niega para créditos. Las notas de crédito de compras pueden mostrar diferencia de IVA.</li><li><strong>Comparación</strong> (<code>Comparar_Comprobantes</code>, <code>:464-524</code>): el IVA de ARCA se compara solo contra el IVA 1 de Procoop; la percepción no se compara.</li></ul><h3 id="_12-7-clsfacturacionvarios-talones-sumados-configuracion-de-impuestos-y-otros" tabindex="-1">12.7 <code>clsFacturacionVarios</code>: talones sumados, configuración de impuestos y otros <a class="header-anchor" href="#_12-7-clsfacturacionvarios-talones-sumados-configuracion-de-impuestos-y-otros" aria-label="Permalink to &quot;12.7 \`clsFacturacionVarios\`: talones sumados, configuración de impuestos y otros&quot;">​</a></h3><p>Esta clase no tiene relación con ARCA; se documenta acá porque es su archivo.</p><ul><li><strong><code>Get_ConceptosIntereses</code></strong> (<code>:252-262</code>): lista <code>CONCEPTOS_INT</code> (base del interés por mora, documento 04) indicando si el concepto es producto, impuesto o servicio y el tipo de interés: <code>TIPO</code> nulo o 0 = entre vencimientos, 1 = mora, otro = ambos (enum <code>Tipo_ConceptoIntereses</code>, <code>:242-250</code>).</li><li><strong><code>Get_TalonesSumados(filtros)</code></strong> (<code>:264-494</code>): consulta los <strong>talones sumados</strong> (filas de <code>TALONFAC</code> con <code>CUOTA = 0</code>, un talón de pago que agrupa varias facturas) en tres modos: por talón (número y rango por fecha de alta o vencimientos 1 a 3), por factura (comprobante y fecha de la factura, y devuelve los talones completos que la contienen) y eliminados (<code>TALONFAC_HST</code>). El talón figura como pagado solo si <strong>todas</strong> sus facturas tienen <code>PAGA = &quot;P&quot;</code>. Defectos: el filtro &quot;hasta&quot; se aplica cuando hay fecha &quot;desde&quot; y falla si falta la fecha &quot;hasta&quot; (<code>:295-298</code>, <code>:323-326</code>), y el valor por defecto de la fecha toma el <code>VTO4</code> del talón incluso en el modo por factura.</li><li><strong><code>Eliminar_Talon(numero)</code> / <code>Eliminar_Talon(lista)</code></strong> (<code>:496-528</code>): no borra de forma definitiva: copia cada fila a <code>TALONFAC_HST</code> con usuario y fecha del servidor (<code>USU_MOD</code>, <code>FEC_MOD</code>) y luego la borra de <code>TALONFAC</code>. La variante de lista lo hace en una sola transacción y revierte todo si falla uno. El parámetro 2360 &quot;Permitir eliminar talones sumados&quot; lo controla la pantalla de caja (documento 05).</li><li><strong><code>Guardar_Impuestos_x_Categoria</code> / <code>Cargar_Configuracion</code></strong> (<code>:547-605</code>): <code>IMPUESTOS_X_CAT</code> guarda, por servicio e impuesto, la <strong>selección de productos y servicios del informe &quot;Impuestos facturados por categoría&quot;</strong> (<code>clsInformes_Facturacion.cs:5216-5232</code>, <code>:6100-6122</code>), como listas de códigos separadas por coma. No es una regla de cálculo de la factura; esto responde la duda del documento 01 sobre esa tabla. La llamada que guarda pasa las listas en orden inverso al de la consulta del informe (<code>:6101</code> contra <code>:6121</code>) <strong>[VERIFICAR]</strong> en pantalla si productos y servicios se recuperan cruzados.</li><li><strong><code>Eliminar_ComprobantesAdministracionPublica(lista)</code></strong> (<code>:624-644</code>): borra de <code>COMPROBANTES_ADM</code> las facturas elegidas (por <code>ID_FAC</code>) dentro de una transacción.</li><li><strong>Defecto en <code>Guardar_ComprobantesAdministracionPublica(…, fechaEmision)</code></strong> (<code>:669-690</code>): el borrado previo arma la fecha con <code>ToShortDateString()</code> <strong>sin comillas</strong> en el SQL, así que el servidor la evalúa como una división y no borra la selección anterior de esa fecha; los nuevos registros se insertan igual y pueden quedar duplicados.</li></ul><p>Métodos sin regla de negocio: <code>Get_InfoPago</code> (pagos de las facturas de un talón: comprobante de caja, número y usuario de caja, recibo, fechas, entrega y banco), <code>Get_ComprobantesAdministracionPublica(periodo)</code> (IDs guardados del período).</p><hr><h2 id="implicancias-para-goodapps" tabindex="-1">Implicancias para GoodApps <a class="header-anchor" href="#implicancias-para-goodapps" aria-label="Permalink to &quot;Implicancias para GoodApps&quot;">​</a></h2><p><strong>Contexto normativo.</strong> Desde fines de 2024 AFIP se llama <strong>ARCA</strong> (Agencia de Recaudación y Control Aduanero, Decreto 953/2024). Los web services no cambiaron de protocolo y siguen publicados bajo los dominios <code>*.afip.gov.ar</code> / <code>afip.gob.ar</code>. Para GoodApps son relevantes:</p><ul><li><strong>WSAA</strong> (<code>LoginCms</code>): obligatorio para todos los servicios. El ticket dura alrededor de 12 h; ARCA rechaza pedir otro mientras el vigente no venza (&quot;el CEE ya posee un TA válido&quot;), así que el caché es obligatorio.</li><li><strong>WSFEv1</strong>: vigente y suficiente para facturas, notas de débito y crédito A/B/C/M, FCE MiPyME y CAEA. Ya incluye <code>CondicionIVAReceptorId</code> (RG 5616) y los arrays <code>Actividades</code> y <code>Compradores</code>.</li><li><strong>WSMTXCA</strong> (con detalle de ítems) y <strong>WSFEXv1</strong> (exportación): no los usa Procoop. Para cooperativas de servicios no son necesarios salvo casos puntuales.</li><li><strong>Padrón</strong>: <code>ws_sr_padron_a13</code> sigue disponible. La consulta de condición fiscal recomendada hoy es <code>ws_sr_constancia_inscripcion</code> (reemplazo del A5). El padrón PUC &quot;nivel 3&quot; (<code>WSPN3</code>) que usa Procoop es un servicio heredado: confirmar si sigue vivo antes de replicarlo; lo más probable es que haya que reemplazarlo.</li><li><strong>Libro IVA Digital</strong> (RG 4597) reemplazó al régimen CITI (RG 3685), pero conserva el diseño de importación de comprobantes y alícuotas: la lógica de exportación de Procoop sigue sirviendo como referencia.</li></ul><p><strong>Recomendaciones de diseño</strong></p><ol><li><strong>Certificados por tenant</strong>: guardar PFX y clave en un almacén seguro (KMS / secret manager), no en una carpeta compartida. Registrar el vencimiento (como el parámetro 2925) con alertas a 30, 14, 7 y 3 días. Soportar homologación y producción por tenant con URLs configurables, en lugar de dejar el padrón fijo en producción como Procoop.</li><li><strong>Caché del ticket</strong> por (CUIT, servicio, ambiente), con renovación anticipada y bloqueo distribuido para que dos workers no pidan ticket a la vez. El <code>uniqueId</code> tiene que ser único de verdad (por ejemplo, basado en la hora), no un contador que vuelve a 0 en cada proceso.</li><li><strong>Cola de autorización</strong> en lugar de <code>ID_BLO = -1</code> + <em>polling</em>: estados explícitos (pendiente → enviando → autorizado / rechazado / a conciliar), un worker por (CUIT, tipo de comprobante, punto de venta) que serialice la numeración, y tandas de hasta el máximo de <code>CantReg</code> que permita ARCA. Conservar las reglas de Procoop que funcionan: <ul><li>no autorizar si hay un número anterior pendiente;</li><li>exigir numeración correlativa;</li><li>ante el error 10016 o un timeout, consultar con <code>FECompConsultar</code> antes de reintentar;</li><li>comparar el total con tolerancia de 0,02.</li></ul></li><li><strong>Lotes B/C</strong>: ARCA permite agrupar comprobantes B a consumidor final por debajo de un monto. Hacerlo configurable y verificar el tope vigente (en Procoop, 5000 por defecto, desactualizado por la inflación).</li><li><strong>Condición IVA del receptor</strong>: es obligatoria según la RG 5616. Mapear la situación IVA de GoodApps al catálogo de <code>FEParamGetCondicionIvaReceptor</code> y no depender del reintento forzando &quot;consumidor final&quot;, que puede informar mal a un receptor exento o monotributista.</li><li><strong>Importes</strong>: trabajar en decimal, no en <code>double</code> como el proxy de Procoop. Reproducir los ajustes de cierre (diferencias menores a 0,03 al exento) y el tratamiento de las facturas C (sin IVA, el exento va al neto).</li><li><strong>Tributos</strong>: armar una tabla de mapeo explícita entre el impuesto de GoodApps y el Id de <code>FEParamGetTiposTributos</code> (1 nacionales, 2 provinciales, 3 municipales, 4 internos, 99 otros, más los códigos específicos de percepciones). No copiar el mapeo directo de Procoop por <code>ORIGEN</code>.</li><li><strong>CAEA</strong>: implementar solicitud por quincena, asignación offline, informe en tandas y también el <strong>informe sin movimiento</strong>, que Procoop no tiene. Verificar las restricciones vigentes de ARCA sobre el uso del CAEA (hay normativa que lo limita a contingencia).</li><li><strong>CESP / LQSP</strong>: si las cooperativas siguen emitiendo liquidaciones de servicios públicos con CESP, modelarlo como &quot;autorización por rango de fechas&quot; separada del CAEA, con validación de superposición correcta (que contemple el caso de contención) y el mismo criterio de vigencia en la emisión, la facturación masiva y la anulación.</li><li><strong>Padrón</strong>: ofrecer autocompletado de razón social, domicilio y condición IVA al dar de alta titulares y proveedores con A13 / constancia de inscripción. Mantener opcional un padrón offline masivo (equivalente a <code>EMPAFIP</code>) para el control periódico de proveedores y titulares.</li><li><strong>Libro IVA</strong>: soportar los cuatro criterios (facturado, percibido, mixto, cuotas vencidas); el percibido es clave para servicios públicos a no inscriptos. Generar el TXT del Libro IVA Digital (ventas y compras con alícuotas) y la conciliación contra &quot;Mis Comprobantes&quot;, idealmente consumiendo la descarga actual en CSV de ARCA en lugar del Excel posicional.</li><li><strong>Modo pasarela</strong>: el modo &quot;solo factura electrónica&quot; de Procoop (CSV de entrada y salida) muestra que hay cooperativas que autorizan comprobantes de otros sistemas. En GoodApps conviene exponerlo como API o importación, no como carpetas compartidas.</li><li><strong>QR y código de barras</strong>: mantener el QR (RG 4892) y el código de barras según el diseño vigente, con <code>tipoCodAut</code> = <code>A</code> para CAEA y <code>E</code> para CAE.</li></ol><h2 id="dudas-abiertas" tabindex="-1">Dudas abiertas <a class="header-anchor" href="#dudas-abiertas" aria-label="Permalink to &quot;Dudas abiertas&quot;">​</a></h2><ol><li><strong>Mapeo de tributos</strong> (resuelta en la segunda pasada, ver §12.2): el código usa la misma convención de <code>IMPUESTO.ORIGEN</code> (1 municipal, 2 provincial, 3 nacional, 4 internos) en todo Procoop y envía ese número como <code>Tributo.Id</code>, así que los municipales y nacionales viajan cruzados y las percepciones de IVA se informan como &quot;impuestos municipales&quot;. Es un defecto del código, no otra convención de datos. Solo queda <strong>[VERIFICAR]</strong> qué orígenes tienen los impuestos cargados en la base de Laguna Larga para medir el impacto.</li><li><strong>CESP</strong>: confirmar con una cooperativa qué norma y procedimiento siguen hoy para las liquidaciones de servicios públicos (tipos 17/18 y RG 3571/RCSP), si el CESP sigue vigente con ARCA y quién lo solicita y carga en <code>CESPAFIP</code> (la pantalla no está en el código relevado).</li><li><strong>CAEA al emitir</strong>: <code>clsComprobante.cs:824-826</code> exige <code>VTO_CESP &amp;lt;= hoy</code> para usar un CAEA, al revés que para el CESP (<code>&gt;= hoy</code>). ¿Es un error del código o <code>VTO_CESP</code> tiene otro significado para los CAEA (por ejemplo, la fecha tope de informe)?</li><li><strong>Parámetro 2427</strong> (importe máximo para autorizar): no se encontró su uso. ¿Lo usa una pantalla que no está decompilada?</li><li><strong>Padrón A13</strong>: <code>GetCuilPersona</code> y <code>GetDatosPersona</code> no tienen llamadas visibles. ¿Se usan desde formularios no relevados o es código muerto?</li><li><strong>Llamadas a <code>ChequearCarpetaIN/OUT</code></strong>: no se encontraron. ¿Qué proceso las ejecuta en el modo solo electrónica (el agente o un formulario) y con qué frecuencia?</li><li><strong>Fila de cabecera con <code>ESTADO = &quot;A&quot;</code></strong> en el libro IVA (<code>clsLibroIVA.cs:1155-1185</code>): ¿&quot;A&quot; significa anulado? Confirmar cómo se presentan los anulados en el libro.</li><li><strong>Errores 10040 / 10242 / 10243</strong>: el tratamiento está claro, pero conviene validar el texto actual de esos códigos en la tabla de errores de WSFEv1, porque ARCA los fue redefiniendo con la RG 5616.</li><li><strong>Posibles defectos a no replicar</strong> (confirmar si afectan en producción): <ul><li><code>RegistrarRel_Comp</code> convierte punto de venta y número a <code>Int16</code> (<code>clsFacturacionElectronica.cs:581-582</code>): falla con números mayores a 32767.</li><li>En la importación CSV, la verificación de duplicados de comprobantes relacionados compara <code>SUC_COM != suc_com</code> (<code>:1419</code>) en lugar de <code>==</code>.</li><li><code>GetDetRequest(ELECTRONICA_FC)</code> evalúa <code>CbtesAsoc.Any()</code> aunque <code>CbtesAsoc</code> pueda ser nulo (<code>:2827</code>).</li><li>En la comparación con &quot;Mis Comprobantes&quot;, <code>Enumerable.Range(desde, hasta)</code> usa el número &quot;hasta&quot; como cantidad (<code>clsLibroIVAdigital.cs:169</code>).</li><li>Cuando el ticket trae varias relaciones, se toma la segunda como CUIT representado (<code>clsFacturacionElectronica.cs:398-401</code>).</li></ul></li><li><strong>Topes y fechas de ARCA</strong>: confirmar al momento de implementar el tope vigente para agrupar comprobantes B, el monto desde el cual es obligatorio identificar al consumidor final, la obligatoriedad efectiva de <code>CondicionIVAReceptorId</code> y las restricciones al CAEA. Todos estos valores cambiaron en los últimos años.</li></ol>`,170)])])}const g=o(t,[["render",r]]);export{m as __pageData,g as default};
